(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-rollout-quant-stable"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-1\">一 · 事故现场：一次“吞吐翻倍”换来的训练崩盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-2\">二 · 它精确处理的那一类误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-3\">三 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-4\">四 · 适用规模的判断依据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-5\">五 · 量化收益吃掉稳定性：一次长 CoT rollout 的分布漂移事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-6\">六 · 失效边界：当 4bit 采样分布偏移无法被 logprob 补偿覆盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-7\">七 · 权重与 scale 的装载：SM 侧的第一步输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-8\">八 · 前向 MMA 与反量化：FP32 累加器是精度锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-9\">九 · logprob 关键路径的补偿：lm_head 与 softmax 的 BF16 重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-10\">十 · 采样与误差估计的记录：比率修正的数据来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-11\">十一 · MoE 路由对齐：被补偿项覆盖不到的失败面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-12\">十二 · 回传与下一轮重新量化：闭环的最后一环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-13\">十三 · 边界不在量化本身，而在补偿链的闭合程度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-14\">十四 · 误差对齐的失效边界与每步代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-15\">十五 · 从 TV 距离到补偿项的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-16\">十六 · 补偿项的构造：从 ε_quant 到 δ_t</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-17\">十七 · 重要性采样比率的修正推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-18\">十八 · 伪代码：可实现的补偿前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-19\">十九 · 误差预算的分配与一个具体例子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-20\">二十 · 推导的边界：补偿项何时失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-21\">二十一 · 误差对齐的边界条件与失效链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-22\">二十二 · 请求形态：为什么长 CoT 批量生成才是它的主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-23\">二十三 · 并发与批大小：动态批下的误差对齐窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-24\">二十四 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-25\">二十五 · 配方与相邻机制的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-26\">二十六 · 规模上限与配方判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-27\">二十七 · 负载配方与失效边界：这套方案在什么请求形态下才成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-28\">二十八 · 硬件档位与量化档位的绑定关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-29\">二十九 · 并行拓扑：以 logprob 路径为锚点切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-30\">三十 · KV 策略：NVFP4 存储与误差估计同生命周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-31\">三十一 · 调度参数：批不变性与量化批次的对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-32\">三十二 · 可复现配置思路：四段式清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-33\">三十三 · 误差对齐配方的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-34\">三十四 · 显存账本：4bit 省下来的不是容量，是容量背后的搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-35\">三十五 · 带宽与通信：省下的 3/4 会被补偿路径吃掉多少</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-36\">三十六 · 功耗与吞吐：张量核心翻倍不等于端到端翻倍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-37\">三十七 · 尾延迟：补偿路径把 P99 拉长的三种方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-38\">三十八 · 规模上去以后哪里先崩：一条判据链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-39\">三十九 · 量化收益在哪个环节被吃掉：带宽账、尾延迟与规模失效点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-40\">四十 · 精度失败的三种指纹：分布偏移、比率失真、KL 漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-41\">四十一 · MoE 路由翻转：补偿项覆盖不到的盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-42\">四十二 · OOM 与批抖动：显存账本的两个漏口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-43\">四十三 · 尾延迟尖刺：从 P99 到单 token 归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-44\">四十四 · 监控埋点与回滚分级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-45\">四十五 · 误差估计回传：把诊断变成修正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-46\">四十六 · 量化误差对齐的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-47\">四十七 · 对照维度：先分清&quot;哪个误差在动&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-48\">四十八 · 决策表：四条稳定化路径的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-49\">四十九 · 与批不变内核的交叉：补偿项不能替代归约确定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-50\">五十 · 与异步权重同步的交叉：陈旧策略下的量化误差会被放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-51\">五十一 · 与分页 KV、前缀共享的交叉：省带宽的收益要不要让给 logprob</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-52\">五十二 · 选型判据落在 ρ_t 方差与 TV 距离的实测上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-rollout-quant-stable-sec-53\">五十三 · 量化误差对齐的适用边界与同族算法选型</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:569px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 569.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎加载NVFP4量化的策略权重，per-block sca…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前向时NVFP4权重与NVFP4激活做张量核心MMA，累加器保持FP32，…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对logprob关键路径（最终lm_head与softmax）用BF16重…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样按补偿后的概率分布进行，记录logprob时同时记录量化误差估计，供训…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout结束后把token、logprob与误差估计回传，训练侧用B…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-1\">一 · 事故现场：一次“吞吐翻倍”换来的训练崩盘</h3>\n<p>先看一个在 Blackwell 集群上真实会发生的失败序列。某 RL 后训练任务把 rollout 引擎从 BF16 切到 NVFP4：权重、激活、KV 全部压到 4bit，decode 吞吐翻倍，长 CoT 样本的生成时间明显缩短，容量规划上原本需要两倍的卡数现在只要一份。上线后前几十个 step 看起来正常，随后 reward 曲线开始缓慢抬升而验证集指标不动——典型的 reward hacking 前兆；再往后 KL 估计出现系统性偏移，重要性采样比率出现极端值，梯度范数尖峰，最终训练崩溃。回滚到 BF16 rollout 后现象消失。问题不在训练侧优化器，也不在数据，而在 rollout 采样分布本身已经被量化误差推离了 BF16 参考分布。</p>\n<p>这条链路的因果很清楚：RL 的更新依赖重要性采样比率 <span class=\"formula-inline\">$\\rho_t = \\pi_{\\theta}(a_t|s_t)/\\pi_{\\text{rollout}}(a_t|s_t)$</span>，分母是 rollout 引擎在采样时记录的 logprob。NVFP4 前向把权重与激活压到 4bit 后，张量核心 MMA 的输入已经带量化误差，累加器虽是 FP32，反量化回 BF16 的输出与 BF16 参考前向并不逐元素相等。softmax 是对数域上的非线性压缩，logits 上一点微小扰动经过指数归一化后，会在低概率尾部被放大成采样概率的显著偏移。于是“采样时用的分布”和“训练时以为的分布”不是同一个分布，比率失真、KL 偏差累积，策略优化方向被系统性带偏。这就是本算法要解决的那个具体问题：不是量化本身慢，而是量化让采样分布不可信。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-2\">二 · 它精确处理的那一类误差</h3>\n<p>把问题形式化，才能划清边界。设 BF16 参考分布为 <span class=\"formula-inline\">$p_{\\text{BF16}}$</span>，NVFP4 路径在补偿后的分布为 <span class=\"formula-inline\">$\\tilde p_{\\text{NVFP4}}$</span>，算法要保证的是两者在全词表上的总变差距离受控：</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>关键在于 <span class=\"formula-inline\">$\\delta_i$</span> 这一项：它不是把 NVFP4 算得更准，而是把已知的量化误差显式建模并补偿回去，使采样概率与 BF16 参考的偏差有界。对应的实现形式是</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>其中 <span class=\"formula-inline\">$W_{\\mathrm{deq}}$</span> 是反量化权重，<span class=\"formula-inline\">$h_t$</span> 是隐状态，<span class=\"formula-inline\">$\\epsilon_{\\mathrm{quant}}$</span> 是被记录并回传训练侧的误差估计。注意这个式子的落脚点是 logprob 路径，不是整张网络：主体矩阵乘仍然走 NVFP4 张量核心，只在最终 lm_head 与 softmax 处用 BF16 重算或叠加补偿项。这个“选择性精确”的选择正是算法适用边界的来源——它救的是采样分布，不是数值精度本身。</p>\n<p>代价随之而来。logprob 路径的 BF16 重算或补偿项要额外算力，lm_head 的词表投影在长 CoT 批量生成里出现频率极高，这部分开销会抵消一部分量化收益；同时补偿项的实现复杂度不低，per-block scale 与 per-tensor scale 必须随权重一同加载到 SM，反量化与补偿要在同一个 kernel 边界内完成，否则误差估计与 logprob 对不上。工程判断是：这笔开销换的是训练稳定性，而不是吞吐，容量规划时必须把它算进 decode 时延预算，不能按纯 NVFP4 的吞吐去承诺 SLO。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-3\">三 · 它不解决什么：三条明确的边界</h3>\n<p>第一条边界是批组成导致的不可复现。同一个 token 在不同 batch 组成下算出不同 logprob，这是批不变内核要处理的问题，与本算法正交。即使 NVFP4 误差被完全补偿，batch 内归约顺序差异仍会让 logprob 抖动，两者叠加时不能指望补偿项兜底。</p>\n<p>第二条边界是 rollout 与训练的串行等待。异步权重同步解决的是引擎空转与权重版本错配，本算法不碰调度层。量化后的权重同步反而更便宜——带宽需求降至 BF16 的 1/4——但同步时机、版本一致性仍归异步流水线管。</p>\n<p>第三条边界最容易被忽视：MoE 路由翻转。NVFP4 下路由 logits 的微小误差足以让 top-k 专家选择改变，同一个 token 在不同量化批次下走不同专家，这种分布偏差是 logprob 补偿项覆盖不了的——补偿项只作用在输出层，而专家选择发生在更早的位置，误差已经通过不同的专家权重放大。因此 MoE 模型必须额外做路由对齐逻辑，否则补偿项再完整也救不回来。这也解释了为什么该算法的收益随模型规模与长 CoT 占比增大：dense 模型与长序列场景里误差主要来自输出层量化，补偿有效；稀疏模型则要先解决路由。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-4\">四 · 适用规模的判断依据</h3>\n<p>适用面可以按三个维度切。硬件维度：只在 Blackwell（SM100/SM103）上有意义，NVFP4 张量核心与 TMEM 是前提，BF16 机器上这套补偿逻辑没有收益。负载维度：请求形态是长 CoT 样本的批量生成，批大小随 rollout 引擎调度动态变化，SLO 以 decode 吞吐与单样本生成时延为主；材料未给出具体批大小数值与 SLO 阈值，只说明权重与 KV 带宽需求降至 BF16 的 1/4。收益随长 CoT 占比增大，因为 decode 阶段是带宽受限的，4bit 权重与 KV 直接砍掉四分之三的搬运量，而补偿项的开销集中在输出层、与序列长度弱相关，长序列摊薄后占比下降。</p>\n<p>不适用或需谨慎的情形同样清晰：如果训练侧对 logprob 精度没有硬要求（例如只用 rollout 做筛选而非做策略梯度），补偿项的算力就是纯浪费；如果模型是 MoE 且没有路由对齐实现，上 NVFP4 rollout 的风险大于收益；如果补偿项实现不完整——只对 softmax 做了 BF16 重算却漏掉 lm_head 的误差估计回传——量化收益被抵消的同时比率仍然失真，等于两头落空。最后一条失败模式尤其隐蔽：量化误差估计若未随 token 与 logprob 一同回传训练侧，训练侧无法修正重要性比率，KL 偏差会持续累积，直到某一步触发 reward hacking 或崩溃，而现场表现与“超参没调好”几乎无法区分。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>适用</th><th>不适用/需额外处理</th></tr></thead><tbody><tr><td>硬件</td><td>Blackwell NVFP4 张量核心</td><td>无 NVFP4 支持的平台</td></tr><tr><td>模型</td><td>dense，输出层误差主导</td><td>MoE，需路由对齐逻辑</td></tr><tr><td>负载</td><td>长 CoT 批量生成，decode 带宽受限</td><td>短样本、算力受限场景</td></tr><tr><td>训练侧</td><td>需要可信 logprob 的策略梯度</td><td>仅做筛选、不修正比率</td></tr></tbody></table>\n<p>落到工程判断上：这套算法的定位是“量化误差对齐层面的稳定化”，它把 NVFP4 rollout 从“能跑”变成“能训”，代价是输出层的一段 BF16 路径和一套必须完整实现的误差回传。上线前要验证的不是吞吐数字，而是补偿后分布与 BF16 参考的 TV 距离是否稳定落在 <span class=\"formula-inline\">$\\epsilon_{\\text{align}}$</span> 以内，以及 MoE 路由在量化前后是否逐 token 一致——这两项不过，吞吐翻倍没有意义。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-5\">五 · 量化收益吃掉稳定性：一次长 CoT rollout 的分布漂移事故</h3>\n<p>把 NVFP4 直接套到 RL rollout 上，最先崩的往往不是算力，而是采样分布。设想一个长 CoT 批量生成任务：rollout 引擎把策略权重与 KV 都压到 NVFP4，decode 吞吐翻倍、单样本生成时延明显缩短，权重与 KV 带宽需求降到 BF16 的 1/4，看上去是一次干净的收益。但采样是对 logprob 精度敏感的操作——量化误差让每个 token 的采样概率相对 BF16 参考发生偏移，这个偏移在几百上千步的 CoT 里逐 token 累积，重要性采样比率 $\\rho_t = \\pi_{\\theta}(a_t|s_t)/\\pi_{\\text{rollout}}(a_t|s_t)$ 随之失真，KL 估计出现系统性偏差。训练侧看到的是一批“看起来正常”的轨迹，实际却来自一个被量化扰动的分布，梯度方向被悄悄带偏，最终表现为 reward hacking 或直接崩溃。这类事故的麻烦在于它不报错、不掉卡，只在训练曲线上以缓慢的形态暴露，等发现时已经烧掉大量 GPU 时。</p>\n<p>这个算法要解决的正是这一层问题：它不是让 NVFP4 更快，而是让 NVFP4 的采样分布与 BF16 参考保持可控距离。机制上按数据流走——rollout 引擎加载 NVFP4 量化的策略权重，per-block scale 与 per-tensor scale 随权重一同加载到 SM；前向时 NVFP4 权重与 NVFP4 激活做张量核心 MMA，累加器保持 FP32，输出经反量化回到 BF16；关键是在 logprob 路径上，对最终 lm_head 与 softmax 用 BF16 重算或加量化误差补偿项，采样按补偿后的分布进行，并把量化误差估计随 token、logprob 一起回传训练侧修正重要性比率。约束可写成</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>其中 $W_{\\mathrm{deq}}$ 为反量化权重、$h_t$ 为隐状态、$\\delta_t$ 为补偿项、$\\epsilon_{\\mathrm{quant}}$ 为记录并回传的误差估计；整体目标则是让 $D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}})\\le \\epsilon_{\\text{align}}$。代价很直接：logprob 路径的 BF16 重算或补偿项增加额外算力与实现复杂度，抵消掉一部分量化收益——省下的是权重与 KV 带宽，付出的是关键路径上的高精度重算，这笔账只有在长 CoT 占比高、模型规模大时才算得过来。</p>\n<p>边界因此很清楚。它适用于 Blackwell 上以 NVFP4 部署 rollout 的 RL 后训练，收益随模型规模与长 CoT 占比增大；但它不解决 batch 组成导致的 logprob 不可复现（那是批不变内核的职责），也不解决 rollout 与训练的串行等待（那是异步权重同步的职责），它只处理 4bit 量化引入的采样分布偏移。失效条件集中在三处：MoE 路由在 NVFP4 下易翻转专家选择，若缺少路由对齐逻辑，同一 token 在不同量化批次下走不同专家，这种分布偏差无法被 logprob 补偿项覆盖；补偿项实现不完整时，量化收益被抵消且重要性采样比率仍会失真；误差估计若未随 token 与 logprob 一同回传，训练侧无从修正比率，KL 偏差累积后照样触发崩溃。工程判断是：先确认 logprob 路径的重算预算与 MoE 路由对齐逻辑是否到位，再决定是否把 rollout 权重压到 NVFP4——否则吞吐翻倍的代价是整轮训练作废。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>NVFP4 rollout（无对齐）</th><th>NVFP4 rollout + 误差对齐</th></tr></thead><tbody><tr><td>权重/KV 带宽</td><td>BF16 的 1/4</td><td>BF16 的 1/4</td></tr><tr><td>logprob 路径</td><td>4bit 直出，偏差无界</td><td>BF16 重算或补偿，偏差受 $\\epsilon_{\\text{align}}$ 约束</td></tr><tr><td>MoE 路由</td><td>专家选择易翻转</td><td>需额外路由对齐逻辑</td></tr><tr><td>训练侧</td><td>比率失真、KL 偏差累积</td><td>凭误差估计修正比率</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-6\">六 · 失效边界：当 4bit 采样分布偏移无法被 logprob 补偿覆盖</h3>\n<p>一个典型的线上事故形态是：rollout 引擎切到 NVFP4 权重与激活后，decode 吞吐按预期提升，但训练侧的 KL 估计在若干步后单调抬升，重要性采样比率的方差迅速放大，最终策略在 reward 上出现明显 hacking 迹象——生成更长、更啰嗦但奖励模型偏爱的样本，而真实任务指标下降。根因不在量化本身，而在采样分布已经偏移：NVFP4 的 per-block scale 与 per-tensor scale 在 SM 上反量化后，lm_head 与 softmax 路径的 logprob 与 BF16 参考出现系统性偏差，采样按偏移后的分布进行，训练侧却仍按名义策略计算比率，$\\rho_t = \\pi_{\\theta}(a_t|s_t)/\\pi_{\\text{rollout}}(a_t|s_t)$ 的分子分母不再对应同一分布。</p>\n<p>本方案的边界正是围绕这一点划定的：它只处理 4bit 量化引入的采样分布偏移，即量化误差对齐层面的稳定化，而不解决 batch 组成导致的 logprob 不可复现（那是批不变内核的职责），也不解决 rollout 与训练的串行等待（那是异步权重同步的职责）。补偿机制要求对最终 lm_head 与 softmax 用 BF16 重算或加误差补偿项，使 $\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t)$ 与 BF16 参考的 TV 距离受控：</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>一旦 $\\epsilon_{\\text{align}}$ 的约束被破坏，补偿项就失效。最典型的破坏源是 MoE 路由：NVFP4 下专家选择的翻转不体现在 logprob 数值上，而体现在同一 token 在不同量化批次走不同专家，此时 $\\delta_t$ 无法覆盖路由层面的分布偏差，必须额外加路由对齐逻辑。第二类失效是补偿项实现不完整——BF16 重算带来的额外算力与实现复杂度会抵消部分量化收益，若只对部分层做重算，剩余层的偏差仍会通过 softmax 放大。第三类是误差估计 $\\epsilon_{\\mathrm{quant}}$ 未随 token 与 logprob 一同回传训练侧，训练侧无法修正比率，KL 偏差累积后触发崩溃。系统代价上，权重与 KV 带宽降至 BF16 的 1/4 是收益侧，但 logprob 路径的 BF16 重算在长 CoT 批量生成中直接占用 decode 时延预算，属于必须计入容量规划的固定开销；适用规模随模型规模与长 CoT 占比增大而收益更明显，但在 MoE 且缺少路由对齐的部署里，这条路径不应开启。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-7\">七 · 权重与 scale 的装载：SM 侧的第一步输入</h3>\n<p>按数据流拆解，rollout 引擎的第一个动作不是前向，而是把 NVFP4 量化后的策略权重连同两级 scale 一起搬进 SM 可见的存储层级。输入是训练侧上一轮更新完的 BF16/FP8 权重，经离线或近线量化后得到 NVFP4 权重张量、per-block scale 与 per-tensor scale；输出是驻留在片上或近片上的量化权重块与配套 scale，供后续 MMA 直接取用。这一步的代价主要落在显存容量与主机到设备带宽上：4bit 权重使权重带宽需求降到 BF16 的 1/4，但 scale 本身是额外负载，per-block 粒度越细，scale 数组越大，装载时的元数据开销越不可忽略。工程上的判断是 scale 粒度与装载路径必须匹配：若 per-block scale 随权重分块排布，则 MMA 前的取 scale 指令可与权重加载流水重叠；若 scale 单独成表，则要多一次索引寻址，decode 阶段每 token 都付这笔钱。</p>\n<p>具体例子：一个 MoE 层在 NVFP4 下权重体积压到 1/4，但每个专家块都带一组 per-block scale，装载器需要按专家路由结果只取被激活专家的权重块与 scale。若把全部专家的 scale 一次性预取，容量收益被吃掉一部分；若按需取，则路由翻转时会出现取块抖动。这一步的输出质量直接决定后面 MMA 的数值起点，因此装载阶段就要保证 scale 与权重块的一一对应关系在 SM 内可寻址。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-8\">八 · 前向 MMA 与反量化：FP32 累加器是精度锚点</h3>\n<p>第二步是前向计算本体。输入是 NVFP4 权重块、NVFP4 激活（由上一层的 BF16 输出即时量化得到）以及对应 scale；计算在 Blackwell 张量核心上以 NVFP4×NVFP4 的 MMA 形式执行，累加器保持 FP32。输出经反量化回到 BF16，进入下一层或进入 logprob 关键路径。这一步的代价是算力与流水编排：4bit MMA 的吞吐优势只有在激活量化、scale 应用、反量化三者都被塞进同一段流水时才兑现，任何一处落到单独的 kernel 都会引入额外的启动与访存开销。FP32 累加器意味着寄存器压力高于纯低精度路径，occupancy 会受影响，这是吞吐换精度的直接代价。</p>\n<p>伪代码思路可写成：对每个 tile，取 <em>W</em><sub>q</sub> 与 <em>h</em><sub>q</sub>，按 scale 还原后送入 MMA，累加结果 <em>acc</em> 保持 FP32，循环结束后 <em>y</em> = dequant(<em>acc</em>) 得 BF16 输出。关键点是反量化不能提前到 MMA 之前——那等于把 4bit 又拉回高精度做乘法，吞吐收益归零；也不能拖到整层之后——那会让中间结果在低精度域里累积误差。累加器留在 FP32、只在出口反量化，是这条路径的精度锚点。</p>\n<p>具体例子：attention 的 QK^T 与 PV 两段若都用 NVFP4 激活，softmax 前的 logits 会带上量化噪声；此时 FP32 累加器保证 logits 的求和误差不随序列长度线性放大，但 logits 本身的低位仍被 4bit 激活截断，这正是下一步必须在 softmax 处补偿的原因。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-9\">九 · logprob 关键路径的补偿：lm_head 与 softmax 的 BF16 重算</h3>\n<p>第三步针对采样分布本身。输入是最后一层隐状态 <em>h</em><sub>t</sub> 与反量化权重 <em>W</em><sub>deq</sub>；输出是补偿后的采样概率 <em>p̃</em><sub>t</sub> 与逐 token 的量化误差估计 <em>δ</em><sub>t</sub>。机制是对最终 lm_head 与 softmax 用 BF16 重算，或等价地加一个量化误差补偿项，使采样概率与 BF16 参考的偏差有界。可写为：</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>这一步的代价是额外算力与实现复杂度：lm_head 的 BF16 重算在词表很大时是一笔可观的矩阵乘，尤其当它被放在每 token 的 decode 路径上；补偿项方案省算力，但要求 <em>ε</em><sub>quant</sub> 的估计足够准，否则补偿本身引入偏差。工程上通常只对 logprob 关键路径做高精度，其余层维持 NVFP4，这样把精度预算集中花在影响采样比率的地方。</p>\n<p>具体例子：词表三十二万级时，lm_head 的 BF16 重算相当于每 token 多一次大矩阵乘；若 rollout 批内 token 数大，这笔开销会明显压低 decode 吞吐。因此实现上多采用“NVFP4 先算 logits、再对 top-k 候选做 BF16 精算”的折中，把重算范围压到真正参与采样的候选上，同时仍记录全分布的误差估计供训练侧使用。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-10\">十 · 采样与误差估计的记录：比率修正的数据来源</h3>\n<p>第四步是采样与记账。输入是补偿后的概率分布 <em>p̃</em><sub>t</sub>；输出是被选中的动作 <em>a</em><sub>t</sub>、其 logprob，以及同 token 绑定的量化误差估计 <em>δ</em><sub>t</sub>。采样按补偿后的分布进行，logprob 记录时同步写入误差估计，供训练侧修正重要性比率：</p>\n<div class=\"formula\">$$\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)}$$</div>\n<p>若 <em>π</em><sub>rollout</sub> 因量化而偏移，<em>ρ</em><sub>t</sub> 就会系统性失真；把 <em>δ</em><sub>t</sub> 随 token 回传，训练侧才能在分母上做修正，而不是被动接受一个有偏的比率。这一步的代价是回传带宽与记录结构：每个 token 多带一个误差标量，长 CoT 样本的 token 数大，累积起来的元数据量与 KV 回传同量级时不可忽视。另一个代价是记录时机——误差估计必须在采样同一时刻捕获，事后补算会失去与当次前向的一致性。</p>\n<p>具体例子：一条长 CoT 样本生成数千 token，每个 token 都带 logprob 与 <em>δ</em><sub>t</sub>；若误差估计只在序列末尾汇总，训练侧无法定位是哪一段的量化误差导致比率偏移，修正只能全局打折，KL 估计偏差仍会累积。逐 token 绑定是让修正可定位的前提。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-11\">十一 · MoE 路由对齐：被补偿项覆盖不到的失败面</h3>\n<p>第五步是 MoE 模型专有的对齐环节。输入是路由 logits 与 NVFP4 下的专家打分；输出是被对齐后的专家选择与相应权重块索引。NVFP4 下路由打分易翻转专家选择，同一 token 在不同量化批次下可能走不同专家，此时采样分布偏差无法被 logprob 补偿项覆盖——因为补偿项作用在输出层，而专家选择改变的是整条前向路径。代价是额外的路由对齐逻辑与可能的二次前向：若对齐后专家与量化前不一致，需要按对齐结果重取权重块，取块抖动直接体现为 decode 时延的尾部抬升。</p>\n<p>工程判断是路由对齐必须在量化前或量化中以确定性方式固化，而不是在采样后补救。具体例子：同一 token 在两次 rollout 中分别命中专家 A 与专家 B，两条路径的隐状态分布不同，logprob 差异远超 <em>δ</em><sub>t</sub> 的量级；此时即便输出层做了 BF16 重算，比率 <em>ρ</em><sub>t</sub> 仍会因路径分歧而失真。路由对齐的价值就在于把这类分歧压到补偿项可覆盖的范围内。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-12\">十二 · 回传与下一轮重新量化：闭环的最后一环</h3>\n<p>第六步是闭环收口。输入是本次 rollout 产出的 token、logprob 与误差估计；输出是训练侧可消费的轨迹数据，训练侧用 BF16/FP8 更新权重，下一轮重新量化后同步回 rollout 引擎。这一步的代价分两段：回传段是主机与设备间的数据搬运，误差估计让每条轨迹的元数据变厚；重新量化段是训练与 rollout 之间的同步等待，量化本身要时间，同步又要保证 rollout 引擎拿到的是同一版本的 scale 与权重，否则比率修正的基准就错位了。</p>\n<p>具体例子：若误差估计未随 token 与 logprob 一同回传，训练侧只能拿到有偏的 <em>π</em><sub>rollout</sub>，修正无从下手，KL 估计偏差在多个迭代里累积，最终表现为 reward hacking 或训练崩溃。反过来，若回传了 <em>δ</em><sub>t</sub> 但重新量化时 scale 版本与记录时不符，修正项与当前分布不匹配，同样失效。因此这一步的工程要点是版本绑定：误差估计必须携带其对应的量化配置标识，训练侧据此判断修正是否可用。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>权重与 scale 装载</td><td>BF16/FP8 权重、量化配置</td><td>NVFP4 权重块 + 两级 scale</td><td>显存容量、H2D 带宽、scale 元数据</td></tr><tr><td>前向 MMA</td><td>NVFP4 权重/激活、scale</td><td>BF16 层输出</td><td>FP32 累加器寄存器压力、流水编排</td></tr><tr><td>logprob 补偿</td><td>隐状态、反量化权重</td><td>补偿后概率、误差估计</td><td>lm_head BF16 重算算力</td></tr><tr><td>采样与记账</td><td>补偿后分布</td><td>动作、logprob、δ<sub>t</sub></td><td>逐 token 元数据回传带宽</td></tr><tr><td>MoE 路由对齐</td><td>路由打分</td><td>对齐后专家索引</td><td>取块抖动、二次前向</td></tr><tr><td>回传与重量化</td><td>轨迹数据</td><td>训练侧样本、新量化权重</td><td>同步等待、版本绑定开销</td></tr></tbody></table>\n<p>把六步串起来看，量化收益的兑现点集中在前两步的带宽与吞吐，而稳定性的兑现点集中在后四步的补偿、记账与对齐。任何一步的代价被低估，都会以比率失真或尾部时延的形式回到系统里：装载阶段的 scale 粒度决定 MMA 前的取数节奏，logprob 路径的重算范围决定 decode 吞吐的上限，误差估计的回传完整性决定训练侧能否真正修正 <em>ρ</em><sub>t</sub>。工程上可操作的判断是先把补偿路径的算力预算与回传元数据预算算清楚，再决定 NVFP4 覆盖到哪一层——覆盖越深，吞吐越高，但对齐与记账的负担越重。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-13\">十三 · 边界不在量化本身，而在补偿链的闭合程度</h3>\n<p>这套机制的失效点几乎都落在“补偿是否闭合”上，而不是 NVFP4 张量核心本身。前向主路径是 NVFP4 权重与 NVFP4 激活做 MMA、FP32 累加、反量化回 BF16，这一步的误差是可建模的；真正危险的是误差估计 $\\epsilon_{\\mathrm{quant}}(W,h_t)$ 没有随 token 与 logprob 一起回传训练侧。此时训练侧拿到的 $\\log \\pi_{\\mathrm{rollout}}$ 已偏移，重要性比率 $\\rho_t$ 的分母失真，KL 估计偏差随步数累积。补偿项必须写成 $$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$ 并保证 $\\delta_t$ 与 logprob 同批次落盘，否则“记录但不回传”等价于没有补偿。</p>\n<p>第二个边界是 MoE 路由翻转。NVFP4 下专家选择的打分差异被压到 4bit 粒度，同一 token 在不同量化批次或不同 per-block scale 下可能落到不同专家；此时 logprob 补偿项只覆盖了数值误差，覆盖不了“走了另一条专家通路”带来的分布偏移。工程判断是：路由对齐逻辑必须独立于 logprob 补偿存在，例如对路由打分保留 BF16 计算或对 top-k 边界做 tie-break 固化，否则 $\\epsilon_{\\mathrm{align}}$ 的上界无法维持。这条代价是实打实的算力——路由层重算会吃掉一部分 4bit 带来的吞吐增益。</p>\n<p>系统代价要按路径分开记账。权重与 KV 以 NVFP4 存储，带宽需求降至 BF16 的 1/4，decode 吞吐与长 CoT 单样本时延受益明显；但 lm_head 与 softmax 的 BF16 重算或补偿项是纯额外算力，且与序列长度线性相关，在长 CoT 批量生成时这部分开销会稀释量化收益。实现复杂度也是代价：per-block scale 与 per-tensor scale 随权重加载到 SM，补偿项要与反量化路径对齐，任何一处遗漏都会让重要性采样比率重新发散。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>表现</th><th>系统代价</th></tr></thead><tbody><tr><td>误差估计未回传</td><td>$\\rho_t$ 分母失真，KL 偏差累积</td><td>训练崩溃或 reward hacking</td></tr><tr><td>MoE 路由翻转</td><td>同 token 走不同专家</td><td>需额外路由对齐算力</td></tr><tr><td>补偿项不完整</td><td>量化收益被抵消</td><td>logprob 路径 BF16 重算开销</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-14\">十四 · 误差对齐的失效边界与每步代价</h3>\n<p>补偿项只在“误差可被记录并被训练侧消费”时成立。若 $\\delta_t$ 只在前向内部使用而不随 token、logprob 一同回传，训练侧拿到的仍是失真的 $\\log \\pi_{\\text{rollout}}$，比率 $\\rho_t$ 的分子分母不在同一精度基准上，KL 估计偏差会跨 step 累积。因此回传链路必须把 $\\epsilon_{\\text{quant}}(W,h_t)$ 与 token 对齐落盘，粒度至少到 per-token，否则补偿只是把偏差从采样端挪到了训练端。这一步的代价不在算力而在带宽与状态：每 token 多一份误差标量，长 CoT 批量生成时回传缓冲随序列长度线性增长，且需与 logprob 同批落盘以保证时序一致。</p>\n<p>MoE 是这套方案最先失效的地方。NVFP4 下路由打分的微小扰动即可翻转 top-k 专家选择，而 logprob 补偿项只覆盖 lm_head 与 softmax 的数值路径，覆盖不了“同一 token 在不同量化批次走不同专家”这一结构性偏移。此时 $\\tilde{p}_t$ 与 $p_{\\text{BF16}}$ 的 TV 距离上界不再由 $\\epsilon_{\\text{align}}$ 约束，因为专家集合本身变了。工程上必须加路由对齐逻辑：路由打分在 BF16 下重算或对 top-k 边界加 margin 判定，代价是每层多一次小矩阵乘与比较，在 MoE 层数多、专家并行度高时这部分开销不可忽略，且 margin 过大会退回 BF16 路由、吃掉量化收益。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主要代价</th></tr></thead><tbody><tr><td>权重/scale 加载</td><td>NVFP4 权重 + per-block/per-tensor scale → SM</td><td>显存占用降至 BF16 的 1/4，加载时延随 scale 元数据增加</td></tr><tr><td>MMA 前向</td><td>NVFP4 权重 × NVFP4 激活 → FP32 累加 → BF16</td><td>张量核心吞吐翻倍，反量化引入额外指令</td></tr><tr><td>logprob 补偿</td><td>$W_{\\text{deq}}h_t+\\delta_t$ → $\\tilde{p}_t$</td><td>lm_head 与 softmax 的 BF16 重算算力，抵消部分量化收益</td></tr><tr><td>采样与回传</td><td>$\\tilde{p}_t$ → token、logprob、$\\epsilon_{\\text{quant}}$</td><td>回传带宽随序列线性增长</td></tr></tbody></table>\n<p>系统代价的账要按路径分开算：decode 吞吐由 KV 以 NVFP4 存储、权重带宽降至 1/4 主导，收益确定；但 logprob 关键路径的 BF16 重算把 lm_head 这一大矩阵乘拉回高精度，词表大、batch 大时该路径占比上升，端到端加速比被压缩。判断这套方案是否划算，看的是长 CoT 样本中补偿路径算力占总 decode 算力的比例——比例低则吞吐收益兑现，比例高则需把补偿限制在采样候选集而非全词表 softmax，用候选集重算换取精度与算力的折中。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-15\">十五 · 从 TV 距离到补偿项的逐项拆解</h3>\n<p>核心不等式是这条：</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>逐项看：左边是 BF16 参考分布与 NVFP4 采样分布的总变差距离，它是重要性采样比率方差的直接上界来源——两个分布 TV 距离为 ε 时，单步比率 ρ_t 的期望偏移量级与 ε 同阶。中间项是逐 token 的 L1 半范数，把两个分布的概率质量差按词表逐项相加。右边 ε_align 是本算法要守住的预算，它不是一个物理常数，而是由训练侧对 KL 估计的容忍度反推出来的工程阈值。关键一步在于：<strong>中间项里的 δ_i 是唯一可设计的自由度</strong>。z_i^BF16 是参考，z̃_i^NVFP4 是量化后的 logits，二者之差由量化决定、不可改；唯有 δ_i 能把这个差拉回来。所以推导的核心问题变成：给定量化误差 ε_quant(W, h_t)，如何构造 δ_i 使 L1 半范数被压到 ε_align 以内。</p>\n<p>把 logits 差写成 Δ_i = z_i^BF16 − z̃_i^NVFP4，则中间项可重写为 Σ_i |p_i^BF16 − softmax(z̃+δ)_i|。softmax 对 logits 的敏感度由概率本身加权：概率越大的 token，其 logit 微扰对分布的影响越大。因此补偿项必须优先对齐高概率 token 的 logits，而不是均匀地给所有 token 加同一个偏移。这一步推导给出两个工程结论：其一，δ_i 应是 per-token、按概率质量加权的，而不是 per-tensor 标量；其二，ε_align 的预算应主要花在 top-k 概率质量上，尾部 token 的误差对 TV 距离贡献有限。代价上，这意味着补偿项的计算量正比于参与对齐的 token 数而非整个词表，是可控的。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-16\">十六 · 补偿项的构造：从 ε_quant 到 δ_t</h3>\n<p>可用事实给出的形式是：</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>这里 W_deq 是反量化权重，h_t 是隐状态，δ_t 是补偿项，ε_quant 是记录并回传的误差估计。推导的关键一步是把 ε_quant 从\"事后统计量\"变成\"前向时可计算的量\"。NVFP4 的量化结构是 per-block scale 加 per-tensor scale，权重与激活各自量化后做 MMA、FP32 累加、再反量化回 BF16。误差来源可分解为三部分：权重舍入误差、激活舍入误差、以及反量化时的 scale 重建误差。前两项在 MMA 前即可由量化器给出（每个 block 的残差范数），第三项由 scale 的表示精度决定。把三者按 block 聚合，就得到 ε_quant(W, h_t) 的一个可计算估计，而不需要 BF16 参考前向来对照。</p>\n<p>工程上 δ_t 有两种落地方式。第一种是<strong>BF16 重算</strong>：对最终 lm_head 与 softmax 这一段，用 BF16 权重与 BF16 隐状态重跑一次矩阵乘，得到精确 logits，代价是这一段完全退出 4bit 路径，算力回到 BF16 水平。第二种是<strong>补偿项注入</strong>：仍在 NVFP4 路径上算 logits，但把 ε_quant 按 block 折算成 logits 空间的加性修正，再进 softmax。前者精度最稳、代价最高；后者省算力，但要求 ε_quant 的估计足够准。实际系统往往混合：lm_head 用 BF16 重算保证采样分布，attention softmax 用补偿项，因为 attention 的 softmax 归一化对 logits 绝对偏移不敏感、只对相对形状敏感。代价上，BF16 重算那一段的算力占比取决于 lm_head 的宽度与 batch 形态，在长 CoT 批量生成里它是固定的每 token 开销，会抵消一部分 4bit 带来的吞吐收益。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-17\">十七 · 重要性采样比率的修正推导</h3>\n<p>比率定义是：</p>\n<div class=\"formula\">$$\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)}$$</div>\n<p>分子是训练侧策略在 BF16/FP8 更新后的概率，分母是 rollout 引擎在 NVFP4 下采样时的概率。若分母用的是未补偿的量化概率，则 ρ_t 系统性偏离 1，且偏离方向随 token 而变——这正是 KL 估计偏差与 reward hacking 的来源。推导的关键一步是：把分母写成补偿后的概率 p̃_t，并把量化误差估计一并回传，则训练侧可以构造一个<strong>双重修正</strong>的比率：</p>\n<div class=\"formula\">$$\\hat\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\tilde{p}_t}\\cdot\\frac{1}{1+\\eta_t},\\quad \\eta_t = \\frac{\\partial \\log \\tilde{p}_t}{\\partial \\delta_t}\\cdot(\\epsilon_{\\text{quant}}^{\\text{residual}})$$</div>\n<p>η_t 是补偿项未完全吸收的残差误差对 logprob 的一阶影响，ε_quant^residual 是回传的误差估计中未被 δ_t 覆盖的部分。这个式子的工程含义是：训练侧不必信任 rollout 的 logprob 是精确的，而是把它当作\"带已知偏差的观测\"，用 η_t 做一阶去偏。代价是训练侧多了一次标量乘加与误差项的存储——每个 token 多存一个误差估计标量，相对 logprob 本身的存储开销可忽略；但若误差估计未随 token 与 logprob 一同回传，这一项就无法计算，KL 偏差会累积，最终触发 reward hacking 或训练崩溃，这是本算法最典型的失败路径。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-18\">十八 · 伪代码：可实现的补偿前向</h3>\n<p>把上述推导落到一个 rollout 前向的伪代码骨架，重点在 logprob 路径的分支与误差记录：</p>\n<ul>\n<li>加载阶段：读入 NVFP4 权重、per-block scale、per-tensor scale，三者一同驻留 SM；同时加载 BF16 的 lm_head 副本（若走重算路线）。</li>\n<li>主干前向：NVFP4 权重 × NVFP4 激活做 tcgen05 MMA，累加器 FP32，逐 block 反量化回 BF16 隐状态 h_t；每个 block 记录该 block 的量化残差范数，聚合成 ε_quant(W, h_t)。</li>\n<li>logprob 分支：若走重算，用 BF16 lm_head 对 h_t 重算 logits；若走补偿，用 NVFP4 logits 加 δ_t = f(ε_quant)，f 为按概率质量加权的对齐函数。</li>\n<li>采样与记录：按 p̃_t 采样 a_t，记录 logprob = log p̃_t(a_t) 与 ε_quant^residual，二者绑定同一 token 写入回传缓冲。</li>\n<li>MoE 分支：路由 logits 单独走 BF16 或加路由对齐逻辑，保证同一 token 在不同量化批次下选中同一专家集合；否则不同 token 走不同专家，分布偏差无法被 logprob 补偿项覆盖。</li>\n</ul>\n<p>这段伪代码里最贵的两处是 BF16 重算的 lm_head 与 MoE 路由对齐。前者是每 token 固定算力，后者是每 token 一次额外的路由比较与可能的专家重排。吞吐代价体现在 decode 阶段：4bit 主干省下的带宽被这两处算力部分吃掉，净收益取决于长 CoT 中 lm_head 调用次数与专家翻转率。显存侧，NVFP4 权重与 KV 存储把带宽需求降到 BF16 的 1/4，这是收益的基本盘；但 BF16 lm_head 副本与误差估计缓冲是额外显存，需要在容量规划里单独计入。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-19\">十九 · 误差预算的分配与一个具体例子</h3>\n<p>ε_align 的预算分配是这套推导的工程落点。把中间项的 L1 半范数按来源拆成三份：权重/激活量化贡献、attention softmax 贡献、MoE 路由贡献。前两份可由 δ_t 直接吸收，第三份不能——路由是离散选择，翻转一次就是整个专家子网络换掉，logits 空间的加性补偿无法覆盖。因此预算分配的原则是：<strong>把 ε_align 的大部分留给连续路径的补偿，路由部分用对齐逻辑单独守住，不纳入 δ_t 的预算</strong>。这解释了为什么 MoE 模型需要额外路由对齐逻辑，而不是靠加大补偿项硬压。</p>\n<p>具体例子：一个长 CoT 样本在 decode 阶段逐步生成，每步都要算 lm_head 与 softmax 得到采样分布。若某步的 ε_quant 估计显示某 block 的权重残差偏大，δ_t 在该 block 对应的高概率 token 上注入修正，使 p̃_t 与 BF16 参考的 TV 距离落在 ε_align 内；同一步若 MoE 路由在 NVFP4 下翻转了专家选择，则补偿项无能为力，必须由路由对齐逻辑在量化前锁定专家集合。系统代价上，前者是每步一次加权对齐的算力，后者是每步一次路由比较的算力与潜在的重排延迟；两者叠加后，单样本生成时延的缩短幅度小于纯 4bit 主干的理论收益，但采样分布偏移受控、比率不发散，训练稳定性接近 BF16 rollout——这是本算法用算力换稳定性的本质交换。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-20\">二十 · 推导的边界：补偿项何时失效</h3>\n<p>补偿项的有效性依赖一个前提：量化误差在 logits 空间是可加、可估的。这个前提在两种情况下失效。其一是误差估计不完整——若 ε_quant 只统计了权重残差而漏掉激活残差或 scale 重建误差，δ_t 会系统性偏小，中间项的 L1 半范数超出 ε_align，比率仍会失真。其二是误差在 batch 维度上不可复现——同一 token 在不同量化批次下若走不同专家，其 logits 差不是加性噪声而是结构性跳变，δ_t 的一阶修正失效。工程判断是：把误差估计的完整性当作正确性条件而非优化项，在回传路径上强制校验 ε_quant^residual 的存在性；对 MoE 模型，路由对齐逻辑必须与 logprob 补偿同时上线，缺一不可。这两条边界决定了本算法在 Blackwell 上 NVFP4 rollout 的收益能否真正兑现——4bit 的带宽红利是确定的，稳定性红利则取决于补偿与对齐两条路径是否都被完整实现。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-21\">二十一 · 误差对齐的边界条件与失效链路</h3>\n<p>补偿项 $\\delta_t$ 的可行性建立在一个前提上：量化误差在给定 $(W,h_t)$ 下是可复现、可估计的量。$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t)$ 中的 $\\delta_t\\approx\\epsilon_{\\mathrm{quant}}(W,h_t)$ 并不是对真实误差的精确还原，而是用记录下来的误差估计做一次一阶修正。这意味着补偿的有效性取决于误差估计与真实前向偏差的一致性：若同一 token 在两次前向中因批组成、KV 分块或路由选择不同而落入不同的量化分块，per-block scale 随之改变，$\\epsilon_{\\mathrm{quant}}$ 的记录值就与当次实际误差脱钩，$\\delta_t$ 反而成为新的偏差源。因此这套方案的硬边界是“误差估计与采样路径同源”——记录误差的那次前向必须就是产生采样概率的那次前向，任何重算、缓存复用或跨批拼接都会破坏这一对应关系。工程上这要求 rollout 引擎把误差估计绑定到 token 级元数据而非批级统计量，代价是每个 token 多携带一份标量误差与对应 scale 标识，回传通路的元数据带宽随生成长度线性增长。</p>\n<p>失效链路最典型的一条在 MoE。NVFP4 下路由打分的微小扰动足以翻转 top-k 专家选择，而专家翻转不是“误差变大”而是“分布换了一支”：$\\tilde{p}_t$ 与 $p_t^{\\mathrm{BF16}}$ 的差异不再落在 $\\epsilon_{\\mathrm{align}}$ 的一阶邻域内，$\\delta_t$ 作为加性补偿项在结构上无法覆盖这种离散跳变。TV 距离的上界在此处失效，重要性采样比率 $\\rho_t$ 出现整段偏移，训练侧看到的 KL 估计偏差不再随 token 数平均而收敛。路由对齐逻辑的必要性正在于此——它必须保证量化前后的专家集合一致，或在翻转时把该 token 标记为不可补偿并降级处理。代价是路由对齐本身要在 NVFP4 打分之外保留一份高精度路由参考，等于在最热的路径上增加一次小算力重算，抵消掉一部分 4bit 带来的吞吐收益。</p>\n<p>第二条失效链路在补偿项的实现完整性。logprob 路径的 BF16 重算或补偿项是纯额外算力：它不参与张量核心 MMA 的吞吐摊薄，却与 MMA 串行或并行竞争 SM 资源。若只对 lm_head 做重算而遗漏 attention softmax 的误差补偿，采样分布的偏差会从注意力权重一侧渗入，$\\epsilon_{\\mathrm{align}}$ 的界不再成立，而表面上 logprob 数值仍然“看起来正常”。这类不完整实现的特征是：短样本上指标正常，长 CoT 上偏差随序列累积放大，最终表现为 $\\rho_t$ 方差抬升与 KL 估计漂移。判断方案是否真正生效，不能看单 token 的 logprob 差值，而要看整条采样轨迹上 $\\rho_t$ 的分布是否与 BF16 rollout 同阶。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被破坏的环节</th><th>系统代价</th></tr></thead><tbody><tr><td>误差估计与采样前向不同源</td><td>$\\delta_t$ 与真实误差脱钩</td><td>token 级元数据带宽上升</td></tr><tr><td>MoE 专家选择翻转</td><td>加性补偿无法覆盖离散跳变</td><td>额外高精度路由参考算力</td></tr><tr><td>补偿项只覆盖 lm_head</td><td>attention softmax 偏差渗入</td><td>长序列偏差累积，$\\rho_t$ 方差抬升</td></tr><tr><td>误差估计未随 token 回传</td><td>训练侧无法修正 $\\rho_t$</td><td>KL 偏差累积，触发 reward hacking</td></tr></tbody></table>\n<p>由此得到一条工程判断：这套方案的收益上界由“可补偿误差占比”决定，而非由 4bit 本身的带宽节省决定。权重与 KV 带宽降至 BF16 的 1/4 是确定的，但 logprob 路径的重算开销、路由对齐开销与误差元数据开销三者叠加，会在长 CoT 占比高、MoE 专家数多的模型上显著侵蚀净收益。规模上限因此不是卡数或显存，而是补偿路径占前向总时间的比例——当该比例逼近量化带来的吞吐增益时，继续压到 NVFP4 就只剩形式上的省带宽，采样分布的稳定性反而要靠更重的 BF16 重算来兜底。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-22\">二十二 · 请求形态：为什么长 CoT 批量生成才是它的主场</h3>\n<p>这套负载配方的第一约束不是硬件，而是请求形态。NVFP4 rollout 稳定化把权重与 KV 压到 4bit，收益来自带宽与张量核心吞吐，而带宽收益只有在 decode 阶段被充分摊薄时才显现：每个 decode step 都要把权重从 HBM 搬进 SM，序列越长、并发越高，单位 token 的权重搬运成本越低，量化省下的 3/4 带宽才真正转化成吞吐。因此它的目标请求形态是长 CoT 样本的批量生成——单条样本动辄数千 token 的推理链，rollout 引擎以动态批调度持续填充 decode 批次。短请求形态（单轮问答、几十 token 的输出）在这个配方下是亏的：decode 步数太少，权重加载与量化 scale 加载的固定开销占主导，而 logprob 路径的 BF16 重算开销按 token 计却是实打实的，量化收益被抵消。</p>\n<p>长度分布决定收益曲线。设单样本生成长度为 $L$，批内并发为 $B$，则单位 token 的权重带宽成本近似正比于 $1/(B\\cdot L)$，而 logprob 补偿路径的算力成本正比于 $L$ 且与 $B$ 无关。二者相交的位置就是这套配方的经济边界：$L$ 越大、$B$ 越饱满，量化净收益越正。长尾长度分布是另一个隐患——若批内长度方差大，短样本先完成、批内并发塌陷，剩余长样本在低并发下继续 decode，恰好落进量化不划算的区间。工程上应让调度器按长度分桶，避免长短混批把收益拖平。</p>\n<p>具体例子：一个以长链推理为主的 RL 后训练任务，rollout 阶段每条样本生成数千 token，批调度维持高并发，NVFP4 权重与 KV 的带宽需求降到 BF16 的 1/4，decode 吞吐显著提升，单样本生成时间缩短；同一引擎若被用来服务短输出请求，logprob 路径的 BF16 重算在每个 token 上都发生，而权重搬运的节省摊不开，端到端时延反而被补偿项拖住。这就是“负载不对”的第一种表现：收益公式的分子没变，分母却按 token 膨胀。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-23\">二十三 · 并发与批大小：动态批下的误差对齐窗口</h3>\n<p>批大小在这套配方里不是吞吐旋钮，而是误差对齐的窗口参数。机制上，rollout 引擎加载 NVFP4 量化权重时，per-block scale 与 per-tensor scale 随权重一同加载到 SM；前向做 NVFP4×NVFP4 的 MMA、FP32 累加、反量化回 BF16，随后在 lm_head 与 softmax 上做 BF16 重算或加补偿项 $\\delta_t$。补偿项的计算与批内 token 数相关：批越大，单次 kernel 启动摊到的补偿算力越便宜，但批内不同序列的量化误差分布差异也越大，$\\delta_t$ 的估计必须逐 token 记录而非批级近似。</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>批大小按 rollout 引擎的调度动态变化，材料未给出具体批大小数值与 SLO 阈值，因此配方只能定性描述：SLO 以 decode 吞吐与单样本生成时延为主，批大小应跟随调度器的连续批处理逻辑，而不是钉死一个静态值。风险在于批组成的漂移——同一 token 在不同批里可能因量化误差估计的批级近似而拿到不同的 $\\delta_t$，采样分布随之抖动。这与批不变内核要解决的问题相邻但不同：批不变内核管的是 batch 组成导致的 logprob 不可复现，本配方管的是 4bit 量化引入的分布偏移；两者叠加时，若 $\\delta_t$ 的估计依赖批统计量，就会把量化误差重新引入批依赖性。</p>\n<p>代价侧：logprob 路径的 BF16 重算或补偿项增加额外算力与实现复杂度。在 decode 吞吐已经翻倍的背景下，这部分算力占比随批大小上升而下降，但随序列长度上升而上升——长 CoT 恰好把两个方向拉满，所以配方必须把补偿路径做成与主 MMA 流水线重叠的旁路，否则它会成为 decode 的关键路径。具体例子：MoE 模型在 NVFP4 下路由易翻转专家选择，若批内 token 的专家分布因量化而分裂，attention softmax 的补偿项无法覆盖路由层的偏差，此时增大批大小只会放大分布偏差而非摊薄成本。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-24\">二十四 · 负载不对时的三种失效形态</h3>\n<p>第一种是短请求高并发形态。请求短、并发高，decode 步数少，权重带宽节省被固定开销吃掉，而每个 token 都要走 BF16 重算的 logprob 路径，端到端时延由补偿算力主导。此时量化收益为负，但系统不会报错——它只是安静地比 BF16 rollout 更慢，容量规划若按“4bit 必快”的假设做，就会低估所需卡数。</p>\n<p>第二种是低并发长尾形态。批内并发塌陷后，剩余长样本在低 $B$ 下继续 decode，权重搬运成本回升到接近 BF16 的水平，而 $\\delta_t$ 的逐 token 记录仍在发生。更隐蔽的是误差估计的回传链路：若量化误差估计未随 token 与 logprob 一同回传训练侧，训练侧无法修正重要性比率，KL 估计偏差累积后可能触发 reward hacking 或训练崩溃。这条失效不体现在 rollout 引擎的吞吐指标上，而体现在训练曲线的漂移上，属于负载配方与训练侧契约的错配。</p>\n<p>第三种是 MoE 路由翻转形态。MoE 路由在 NVFP4 下易翻转专家选择，若缺少路由对齐逻辑，同一 token 在不同量化批次下走不同专家，采样分布偏差无法被 logprob 补偿项覆盖。此时 $\\rho_t = \\pi_{\\theta}(a_t|s_t)/\\pi_{\\text{rollout}}(a_t|s_t)$ 的分子分母建立在不同的专家路径上，比率失真不是数值噪声而是结构性偏差，任何 $\\epsilon_{\\text{align}}$ 都无法把它压回界内。负载配方对此的防御是：把路由对齐逻辑放在量化加载阶段而非前向阶段，让专家选择在量化前后保持一致，代价是额外的路由重算算力。</p>\n<ul>\n<li>失效一：短请求高并发——补偿算力主导时延，量化净收益为负。</li>\n<li>失效二：低并发长尾——带宽节省回落，误差估计回传缺失导致 KL 偏差累积。</li>\n<li>失效三：MoE 路由翻转——分布偏差结构性存在，补偿项覆盖不到。</li>\n</ul>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-25\">二十五 · 配方与相邻机制的边界划分</h3>\n<p>这套负载配方必须与相邻的稳定化机制划清边界，否则工程上会把不同来源的 logprob 偏差混为一谈。批不变内核解决的是 batch 组成导致的 logprob 不可复现；异步权重同步解决的是 rollout 与训练的串行等待；本配方专门处理 4bit 量化引入的采样分布偏移，属于量化误差对齐层面。三者的失效表现可以叠加：一个批组成漂移的请求，若同时落在低并发长尾区间，量化误差与批依赖误差会同时进入 $\\rho_t$，此时单独修任何一个机制都不足以让比率收敛。</p>\n<p>边界划分的工程判据是误差来源的可观测性。量化误差有显式的估计量 $\\epsilon_{\\mathrm{quant}}(W,h_t)$ 随 token 回传，可被训练侧直接用于修正；批依赖误差没有这样的显式估计量，只能靠批不变内核从调度层消除。因此负载配方要求调度器在分桶时同时考虑长度与批组成稳定性，把量化误差可估计的请求与批依赖误差敏感的请求分开处理。代价是调度复杂度上升，收益是 $\\rho_t$ 的失真来源可归因。</p>\n<p>具体例子：一个长 CoT 批量生成任务同时启用了分页 KV 与连续批处理，若调度器把长短样本混批，短样本完成后批内并发下降，剩余长样本进入量化不划算区间，同时批组成变化引入批依赖误差；此时即便 $\\delta_t$ 记录完整，训练侧也只能修正量化部分，批依赖部分仍会污染 KL 估计。配方层面的解法是按长度分桶并保持桶内并发饱满，让两类误差不同时发生。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-26\">二十六 · 规模上限与配方判据</h3>\n<p>适用边界与规模上限：适用于 Blackwell 上以 NVFP4 部署 rollout 的 RL 后训练，收益随模型规模与长 CoT 占比增大。模型越大，权重带宽在 decode 成本中的占比越高，1/4 带宽的节省越显著；长 CoT 占比越高，单位 token 的固定开销摊得越薄。反过来，小模型加短请求的组合会让这套配方失去经济性，此时应退回 BF16 rollout 或仅在 KV 存储上使用 NVFP4。</p>\n<p>配方判据可以写成一个定性不等式：量化净收益为正，当且仅当权重带宽节省超过 logprob 补偿算力与路由对齐算力之和。前者随 $B\\cdot L$ 增大，后者随 $L$ 与 MoE 专家数增大。工程上应把这条判据做成调度器的准入条件：对每条请求估计其 $L$ 与所属桶的 $B$，若落在补偿算力主导区间，则将该请求路由到 BF16 路径或延迟到并发更饱满的批次。这样做的代价是路径分裂带来的实现复杂度，收益是避免“量化了却更慢”的隐性亏损。</p>\n<p>最后落在具体机制上：配方要求 rollout 引擎在加载 NVFP4 权重的同时加载 per-block 与 per-tensor scale 到 SM，并在前向的 lm_head 与 softmax 处插入 BF16 重算或补偿项 $\\delta_t$，逐 token 记录 $\\epsilon_{\\mathrm{quant}}$ 并随 logprob 回传。负载配方的全部工作，就是保证这条补偿链路只在它能盈利的请求形态上被激活——长 CoT、批饱满、路由对齐；一旦请求形态偏离，补偿链路的算力开销就会从“可摊薄”变成“纯亏损”，而训练侧收到的误差估计若仍按量化路径的假设去修正比率，KL 偏差会在无人察觉的情况下累积。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-27\">二十七 · 负载配方与失效边界：这套方案在什么请求形态下才成立</h3>\n<p>这套量化稳定方案不是通用加速开关，它的收益结构由请求形态决定。适配的负载是长 CoT 样本的批量生成：单条序列解码步数多、KV 常驻显存占比高、decode 阶段受带宽约束，此时把权重与 KV 压到 4bit（带宽需求降至 BF16 的 1/4）直接转化为单样本生成时延下降，收益随长 CoT 占比与模型规模放大。批大小交给 rollout 引擎调度动态决定，SLO 以 decode 吞吐与单样本时延为主，材料未给出具体批大小与阈值。反过来，短输出、高并发、以首 token 时延为主的请求形态里，prefill 算力占比上升而带宽节省摊薄，logprob 路径的 BF16 重算开销反而成为主导项。</p>\n<p>负载不对时的失效不是渐变而是结构性失真。核心约束是采样分布与 BF16 参考的 TV 距离必须被补偿项压住：</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\epsilon_{\\text{align}},\\quad \\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t)$$</div>\n<p>一旦批次组成频繁变化、序列长度分布极度不均，per-block scale 的统计基础被破坏，$\\delta_t$ 的补偿前提不再成立；MoE 模型更敏感——NVFP4 下路由易翻转专家选择，同一 token 在不同量化批次走不同专家，这种偏差无法被 lm_head 与 softmax 的补偿项覆盖，必须额外加路由对齐逻辑。若量化误差估计没有随 token 与 logprob 一同回传训练侧，重要性采样比率 $\\rho_t$ 无法修正，KL 估计偏差累积后触发 reward hacking 或训练崩溃。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>方案表现</th><th>系统代价</th></tr></thead><tbody><tr><td>长 CoT、大批量 decode</td><td>带宽降至 1/4，吞吐与时延双收益</td><td>logprob 路径 BF16 重算占用算力</td></tr><tr><td>短输出、prefill 为主</td><td>带宽节省摊薄，补偿开销占比上升</td><td>量化收益被部分抵消</td></tr><tr><td>MoE 且批次组成多变</td><td>路由翻转，分布偏差超出补偿范围</td><td>需路由对齐逻辑，实现复杂度上升</td></tr></tbody></table>\n<p>工程判断落在容量规划上：按长 CoT 占比估算收益上限，同时为 logprob 关键路径预留 BF16 算力预算，并把路由对齐与误差回传当作必选组件而非优化项——缺任一项，4bit 的吞吐翻倍就会以训练稳定性为代价被赎回。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-28\">二十八 · 硬件档位与量化档位的绑定关系</h3>\n<p>部署配方的第一层决策不是选卡数，而是把量化档位与硬件能力绑定死。Blackwell 上 NVFP4 张量核心的可用性决定了 rollout 引擎能否把权重与激活同时压到 4bit：权重走 NVFP4、激活走 NVFP4、累加器保持 FP32，这条路径只有在 SM100/SM103 的 tcgen05 MMA 上才有意义。若把同一份 NVFP4 权重搬到不支持该指令形态的档位上跑，反量化开销会吃掉带宽收益，rollout 的 decode 吞吐反而低于 BF16 基线。因此配方里必须显式声明档位约束：rollout 引擎实例只在 Blackwell 档位注册，量化方案与档位一一对应，不做跨档位回退。</p>\n<p>量化方案本身要拆成三段描述，而不是一句“用 NVFP4”。第一段是权重侧：per-block scale 与 per-tensor scale 随权重一同加载到 SM，scale 的加载路径与权重同生命周期，避免每步前向重新计算。第二段是激活侧：激活同样量化为 NVFP4，但反量化后的输出必须回到 BF16 再进入 logprob 关键路径。第三段是累加器：MMA 内部保持 FP32，这是保证 4bit 乘加不产生系统性偏置的前提。三段缺一，采样分布偏移就无从界定。</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$$</div>\n<p>这条式子就是配方里“量化档位”一项的验收标准：任何配置组合都必须能算出 $\\delta_t$ 并随 token 回传，否则该组合不进入生产配方。代价方面，权重与 KV 带宽需求降至 BF16 的 1/4，这是配方中唯一可以写死的定量收益；而 logprob 路径的 BF16 重算带来的额外算力属于必须计入的固定成本，不能当作可选项。举例：一个长 CoT 批量生成任务，若把 lm_head 也整体 NVFP4 化而不留 BF16 重算分支，采样概率与 BF16 参考的 TV 距离会越过 $\\epsilon_{\\text{align}}$，此时即便吞吐翻倍，重要性采样比率也会在若干步后发散，配方应判定为不合格。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-29\">二十九 · 并行拓扑：以 logprob 路径为锚点切分</h3>\n<p>并行拓扑的切分原则不是按算力均分，而是按“哪些计算必须保持高精度”来划分。配方中把前向切成两类区域：主体 MMA 区域走 NVFP4 张量核心，可自由做张量并行与专家并行；logprob 关键路径（最终 lm_head 与 softmax）走 BF16 重算，其并行切分必须保证每个 token 的完整 logits 向量落在同一设备或同一通信组内，避免跨设备归约引入额外的数值抖动。这条约束直接决定拓扑形状：lm_head 的切分维度不能与隐状态切分维度冲突，否则重算分支需要 all-gather 才能拼出完整分布。</p>\n<p>对 MoE 模型，拓扑还要额外容纳路由对齐逻辑。NVFP4 下路由打分易翻转专家选择，配方要求路由计算在 BF16 下完成、专家选择结果广播到所有持有该 token 的设备，再由各设备按同一专家集合执行 NVFP4 MMA。这样同一 token 在不同量化批次下走同一组专家，分布偏差才落在 $\\delta_t$ 可覆盖的范围内。代价是路由阶段多一次小规模广播，延迟量级远小于专家权重的 all-to-all，但若省略，失败模式立刻显现：同一 token 在不同批次命中不同专家，logprob 补偿项无法覆盖这种离散跳变。</p>\n<table class=\"mini\"><thead><tr><th>拓扑区域</th><th>精度</th><th>切分约束</th><th>系统代价</th></tr></thead><tbody><tr><td>主体 MMA</td><td>NVFP4×NVFP4，FP32 累加</td><td>张量/专家并行自由切分</td><td>带宽降至 1/4，吞吐主收益来源</td></tr><tr><td>lm_head + softmax</td><td>BF16 重算</td><td>单 token logits 不跨组</td><td>额外算力，抵消部分量化收益</td></tr><tr><td>MoE 路由</td><td>BF16 打分</td><td>专家集合全局一致</td><td>一次小广播，避免专家翻转</td></tr></tbody></table>\n<p>具体例子：一个专家并行的 MoE rollout 实例，若把路由打分也放进 NVFP4 MMA，某些 token 的 top-k 专家在相邻两步间跳变，采样分布出现不连续，训练侧看到的重要性采样比率 $\\rho_t$ 出现尖峰。配方在此处的工程判断是：路由精度不可压缩，压缩它就等于放弃 $\\delta_t$ 的可界定性。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-30\">三十 · KV 策略：NVFP4 存储与误差估计同生命周期</h3>\n<p>KV 以 NVFP4 存储是配方中省带宽的主要手段，但 KV 量化引入的误差与权重误差叠加方式不同：权重误差在每步前向重复出现，KV 误差则随上下文增长累积。配方因此要求 KV 的量化 scale 与 KV 块同生命周期管理，块被换出再换入时 scale 必须一并迁移，不能重算，否则同一段上下文在不同时刻的反量化结果不一致，logprob 不可复现。这与分页 KV 的管理粒度直接相关：页表项里除块地址外还要挂 scale 句柄。</p>\n<p>KV 策略的第二条是误差估计的存放位置。$\\epsilon_{\\mathrm{quant}}$ 不能只存在于 rollout 引擎的临时缓冲，必须与 token、logprob 一起进入回传队列，且 KV 侧的量化误差要按块聚合后并入该 token 的误差估计。配方给出的伪代码思路是：每个 decode step 结束时，把本步 attention 输出的反量化残差按头聚合，写入该 token 的误差记录槽；rollout 结束后整批回传，训练侧据此修正 $\\rho_t$。若误差估计未随 token 与 logprob 一同回传，训练侧无法修正重要性比率，KL 估计偏差累积后可能触发 reward hacking 或训练崩溃——这是配方中列为阻断级失败模式的唯一一条。</p>\n<p>代价上，NVFP4 KV 把 KV 带宽压到 BF16 的 1/4，长 CoT 场景下显存占用同步下降，允许更大批量的动态调度；但误差记录的存储与回传增加了一次写放大，量级与 token 数成正比。工程判断是：误差记录的写放大远小于 KV 带宽收益，配方中不设开关，始终开启。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-31\">三十一 · 调度参数：批不变性与量化批次的对齐</h3>\n<p>调度参数的第一项是批组成策略。批不变内核解决的是 batch 组成导致的 logprob 不可复现，本配方在此之上追加一条：同一 token 的量化批次归属必须稳定。配方要求调度器在组批时记录每个请求的量化批次标识，同一请求在其生命周期内不跨批次迁移，避免同一 token 在不同量化批次下走不同专家。这条约束与连续批处理的动态插入存在张力：新请求插入会改变批组成，配方允许插入，但插入后必须重新广播专家集合，而不是让旧 token 沿用旧集合。</p>\n<p>第二项是 logprob 重算分支的调度优先级。BF16 重算比 NVFP4 MMA 慢，若与主体计算同优先级排队，会拖长单样本生成时延。配方把重算分支放在独立的执行流，与下一批的 MMA 重叠，用流水掩盖其延迟。第三项是误差估计的回传节流：回传队列按 token 批量打包，避免逐 token 通信，但打包延迟不得超过一个调度周期，否则训练侧拿到的 $\\rho_t$ 修正滞后于权重更新节奏。</p>\n<div class=\"formula\">$$\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)}$$</div>\n<p>调度参数的验收方式是看 $\\rho_t$ 的分布宽度：配方要求在同一权重版本下，$\\rho_t$ 的离散度不随批大小变化而显著漂移。若漂移，说明量化批次归属或专家集合广播出了问题，而非采样本身。举例：动态批大小在长 CoT 生成中从个位数涨到数十，若调度器未固定量化批次标识，$\\rho_t$ 的尾部会随批大小变宽，训练侧误判为策略漂移。配方在此处的判断是：调度参数的稳定性优先于批大小的极致利用。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-32\">三十二 · 可复现配置思路：四段式清单</h3>\n<p>把上述决策收敛成一份可复现的配置，按四段写，每段都带验收条件，而不是带数值。第一段硬件与量化：档位限定 Blackwell，权重 NVFP4、激活 NVFP4、累加器 FP32，scale 随权重加载到 SM；验收条件是能对任意 batch 算出 $\\delta_t$ 并回传。第二段并行拓扑：主体 MMA 自由切分，lm_head 与 softmax 走 BF16 重算且单 token logits 不跨组，MoE 路由 BF16 打分并全局广播专家集合；验收条件是同一 token 相邻两步专家集合一致。第三段 KV：NVFP4 存储，scale 与块同生命周期，误差按块聚合并入 token 误差记录；验收条件是同一上下文换出换入后 logprob 可复现。第四段调度：量化批次标识随请求固定，重算分支独立执行流，误差回传按周期打包；验收条件是 $\\rho_t$ 离散度不随批大小漂移。</p>\n<p>这份清单的复现性来自“每段一个可观测验收条件”，而非固定超参。材料未给出具体卡数、批大小数值与 SLO 阈值，配方因此不写死这些量，只写它们必须满足的不变量。工程上这意味着换一个集群规模，配置文本不变，变的只是拓扑展开后的设备映射。代价评估也按段计：第一段拿带宽 1/4 的收益，第二段付重算算力，第三段付误差写放大，第四段付调度保守性带来的批利用率损失。四段相加才是净收益，任何单段的最优化都不构成配方。</p>\n<p>具体例子：若把第二段的重算分支省掉以追求吞吐，第一段的带宽收益仍在，但 $\\epsilon_{\\text{align}}$ 失去约束对象，第三段的误差记录变成无源之水，第四段的 $\\rho_t$ 验收必然失败。配方在此处的工程判断是：四段是串联依赖，不是可裁剪的选项列表；省掉任何一段，省下的算力都会以训练不稳定性的形式还回来。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-33\">三十三 · 误差对齐配方的失效边界与系统代价</h3>\n<p>这套配方的稳定性不来自“把权重压到 4bit”本身，而来自一条被显式约束的误差通道：采样分布与 BF16 参考的 TV 距离必须落在 ε<sub>align</sub> 之内，重要性采样比率 ρ<sub>t</sub> 才不发散。边界条件因此很硬——一旦补偿项 δ<sub>t</sub> 的实现不完整，公式右端的界就失效，而吞吐收益仍照常兑现，形成“快但漂”的危险组合。具体失效点有三类：其一，logprob 路径若只对 lm_head 做 BF16 重算却漏掉 softmax 前的累加误差，δ<sub>t</sub> 被低估，采样概率偏差被系统性掩盖；其二，MoE 路由在 NVFP4 下翻转专家选择，同一 token 在不同量化批次走不同专家，这种偏差无法被逐 token 的 logprob 补偿项覆盖，因为误差源在路由而非数值；其三，量化误差估计 ε<sub>quant</sub> 未随 token 与 logprob 一同回传，训练侧无从修正 ρ<sub>t</sub>，KL 偏差累积后触发 reward hacking。三者共同说明：配方的可复现性依赖“误差可观测”这一前提，而非量化位宽本身。</p>\n<p>系统代价必须按路径拆开核算。NVFP4 权重与 KV 存储把带宽需求降至 BF16 的 1/4，decode 吞吐与长 CoT 样本生成时间显著受益；但 logprob 关键路径的 BF16 重算或补偿项是纯增量算力，且与采样强同步——它落在每步 decode 的尾端，无法被批调度掩盖。设单步 decode 的基线时间为 T<sub>mma</sub>（NVFP4 张量核心 MMA，FP32 累加器），补偿路径耗时为 T<sub>comp</sub>，则有效加速比被压缩为：</p>\n<div class=\"formula\">$$S_{\\text{eff}}=\\frac{T_{\\text{BF16}}}{T_{\\text{mma}}+T_{\\text{comp}}},\\qquad \\text{s.t.}\\ D_{\\text{TV}}\\le\\epsilon_{\\text{align}}$$</div>\n<p>当 T<sub>comp</sub> 随词表规模与 batch 内 token 数增长时，S<sub>eff</sub> 会明显低于 2× 的名义吞吐翻倍；这正是“抵消部分量化收益”的定量含义。工程判断是：把补偿做成只覆盖最终 lm_head 与 softmax 的窄路径，而非全前向 BF16 回退，否则配方退化为 BF16 rollout 加一次无谓的量化往返。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>补偿项漏掉累加误差</td><td>ρ<sub>t</sub> 方差随步数上升</td><td>KL 偏差累积，训练侧需回滚</td></tr><tr><td>MoE 路由翻转</td><td>同 token 跨批次专家不一致</td><td>分布偏差不可补偿，需路由对齐逻辑</td></tr><tr><td>ε<sub>quant</sub> 未回传</td><td>训练侧无修正依据</td><td>重要性采样比率失真，吞吐收益被稳定性事故吞掉</td></tr></tbody></table>\n<p>并行拓扑与硬件档位的选择受同一约束支配：scale 随权重加载到 SM，per-block 与 per-tensor scale 的粒度决定了反量化开销能否被 MMA 流水掩盖；若并行切分使某卡上的 scale 重载频繁，T<sub>comp</sub> 之外的额外同步会进一步侵蚀 S<sub>eff</sub>。因此配方的可复现写法应把“误差界”作为一等配置项与批大小、KV 策略并列声明，而不是事后调参：先固定 ε<sub>align</sub> 与 ε<sub>quant</sub> 的回传格式，再让调度参数在满足该界的前提下最大化 decode 吞吐。收益随模型规模与长 CoT 占比增大，但规模上限由补偿路径的相对开销与路由翻转概率共同决定——超过该点，NVFP4 rollout 的稳定性成本高于其带宽节省。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-34\">三十四 · 显存账本：4bit 省下来的不是容量，是容量背后的搬运</h3>\n<p>把 rollout 权重与 KV 压到 NVFP4，账面收益是 1/4 的字节数，但真正被改变的是每步 decode 必须搬动的字节数。decode 阶段每生成一个 token，都要把参与计算的权重从 HBM 搬到 SM 附近的存储层级，再与激活做 MMA；算术强度极低，瓶颈在搬运而非算力。因此 NVFP4 的收益首先体现在带宽侧：权重与 KV 带宽需求降至 BF16 的 1/4，等价于在同样的 HBM 带宽下把可服务的并发序列数抬上去。但显存容量的节省并不等于可以无脑放大批——KV 以 NVFP4 存储时，per-block scale 与 per-tensor scale 必须与权重、KV 一同驻留并被加载到 SM，这部分元数据随 block 粒度变细而膨胀，是容量账本里容易被忽略的固定开销。</p>\n<p>更关键的是 logprob 路径的 BF16 残差校正。对最终 lm_head 与 softmax 用 BF16 重算，意味着这条路径上要保留一份 BF16 的权重副本或至少保留可重算的中间量；若采用补偿项路线，则需保存 $\\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t)$ 的估计。两种做法都在 NVFP4 的显存账本上叠加了一块 BF16 级别的影子开销，且这块开销随词表规模线性增长——lm_head 是大词表模型里最胖的单层之一。工程判断是：容量规划不能按“权重 4bit + KV 4bit”直接除以 4 来估算可承载并发，必须把 scale 元数据、BF16 重算副本或补偿项缓冲、以及误差估计回传缓冲一并计入，否则规模上去后最先崩的是显存而不是算力。</p>\n<div class=\"formula\">$$M_{\\text{rollout}} \\approx \\underbrace{\\tfrac{1}{4}M_{W}}_{\\text{NVFP4 权重}} + \\underbrace{\\tfrac{1}{4}M_{KV}}_{\\text{NVFP4 KV}} + \\underbrace{M_{\\text{scale}}}_{\\text{per-block/per-tensor}} + \\underbrace{M_{\\text{corr}}}_{\\text{BF16 重算或 }\\delta_t}$$</div>\n<p>举例：一个长 CoT 批量生成任务，序列长度随推理步数持续增长，KV 是随时间膨胀的动态项，而 $M_{\\text{corr}}$ 是静态项。当并发序列数翻倍时，KV 项线性翻倍，$M_{\\text{corr}}$ 不变，但 $M_{\\text{scale}}$ 随 KV block 数增长。于是显存压力的构成会随规模发生迁移：小规模时权重占主导，大规模时长 CoT 的 KV 与 scale 元数据占主导。这决定了扩容时该优先压缩哪一项。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-35\">三十五 · 带宽与通信：省下的 3/4 会被补偿路径吃掉多少</h3>\n<p>NVFP4 把权重与 KV 的搬运量降到 1/4，但 logprob 关键路径的 BF16 重算会在每一步 decode 上追加一次额外的读与算。设 BF16 路径只覆盖 lm_head 与 softmax，则每 token 的额外搬运量与词表规模成正比，而 NVFP4 省下的是全部层权重与 KV 的搬运。两者不是同一量级，因此在长 CoT、小批的 decode 场景里净收益为正；但在短序列、大词表、且补偿项实现不完整的配置下，额外算力与实现复杂度会抵消部分量化收益——这正是该算法代价栏里写明的取舍。</p>\n<p>通信侧的变化更隐蔽。分离式预填/解码或 KV 中心池化部署下，KV 需要在节点间经 NVLink 5 与 NCCL/NIXL 搬运。KV 以 NVFP4 存储使跨节点传输字节数降至 1/4，直接压低传输时延与链路占用，这是规模上去后最立竿见影的一项。但误差估计 $\\epsilon_{\\mathrm{quant}}$ 必须随 token 与 logprob 一同回传训练侧，供训练侧修正重要性比率 $\\rho_t$；这条回传通路是新增的通信量，虽然远小于 KV，却引入了新的同步点。若误差估计未随 token 与 logprob 一同回传，训练侧无法修正重要性比率，KL 估计偏差累积后可能触发 reward hacking 或训练崩溃——这不是性能问题，是正确性问题。</p>\n<div class=\"formula\">$$\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)},\\qquad \\text{分母需用补偿后的 }\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t)$$</div>\n<p>工程上要把回传通路做成与 token 流同批的背驮结构，而不是独立 RPC：误差估计与 logprob 同生命周期，随 rollout 结果一起落盘或入队，避免为每条序列增加一次往返。规模上去后，通信先崩的位置通常不是 KV 传输本身，而是这些“小但同步”的旁路通道在并发序列数增大时形成的控制面拥塞。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-36\">三十六 · 功耗与吞吐：张量核心翻倍不等于端到端翻倍</h3>\n<p>NVFP4 张量核心让 MMA 的吞吐翻倍，但端到端 decode 吞吐受限于搬运、softmax、采样与 logprob 补偿这几段非 MMA 路径。Amdahl 式的分解在这里很直接：设 MMA 段占比为 $f$，则理论加速上限为 $1/((1-f)+f/2)$。长 CoT 场景里 MMA 段占比高，收益接近翻倍；短输出、大词表场景里 lm_head 与 softmax 占比抬升，BF16 重算又把这段的算力需求拉回去，净加速被压缩。功耗侧同理：4bit MMA 的单位操作能耗低于 BF16，但补偿路径的 BF16 重算在功耗账本上是纯增量，且它落在每 token 的必经路径上，无法通过批调度摊薄。</p>\n<p>具体例子：MoE 模型在 NVFP4 下做 rollout，路由网络若也用 4bit 计算，专家选择容易翻转。翻转意味着同一 token 在不同量化批次下走不同专家，激活分布随之跳变，采样分布偏差无法被 logprob 补偿项覆盖——因为补偿项是对已选专家的输出做校正，管不了“选错专家”这件事。因此 MoE 需要额外的路由对齐逻辑，通常是把路由的 logits 计算保留在更高精度或加误差补偿，这又是一块不产生吞吐收益的算力开销。规模上去后，MoE 的路由对齐开销随专家数与 token 数同时增长，是功耗与延迟账本里最先失控的项之一。</p>\n<div class=\"formula\">$$S_{\\text{e2e}} \\le \\frac{1}{(1-f_{\\text{MMA}})+f_{\\text{MMA}}/2},\\qquad f_{\\text{MMA}} \\text{ 随输出长度上升、随词表规模下降}$$</div>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-37\">三十七 · 尾延迟：补偿路径把 P99 拉长的三种方式</h3>\n<p>平均吞吐好看不代表 SLO 达标。NVFP4 rollout 的尾延迟有三个放大源。其一是 BF16 重算路径的排队：当批内序列长度差异大时，长 CoT 序列在 lm_head 上的 BF16 重算耗时远高于短序列，连续批处理下这条路径成为批内最慢成员的瓶颈，P99 由最长序列决定。其二是 MoE 路由翻转带来的专家负载不均：翻转使某些专家的 token 数在批次间剧烈波动，专家并行下的 all-to-all 通信出现热点，尾延迟被最热专家拉长。其三是误差估计回传的同步点，若回传与下一轮权重同步耦合，一次慢回传会阻塞整条流水线。</p>\n<p>控制手段要落在调度层而非算子层：按序列长度分桶、把长 CoT 序列集中到专门批次以摊薄 BF16 重算的固定开销；对路由翻转做批次级的专家选择一致性检查，发现翻转率超阈值时降级到更高精度的路由；误差估计回传走异步队列并与权重同步解耦。这里与批不变 Rollout 采样的关注点不同——后者解决 batch 组成导致的 logprob 不可复现，本算法处理的是 4bit 量化引入的分布偏移，两者在尾延迟上叠加：批组成变化会改变量化误差的统计特性，使补偿项的校准在批次切换时短暂失准。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-38\">三十八 · 规模上去以后哪里先崩：一条判据链</h3>\n<p>把上述账本按规模排序，可以得到一条工程判据链。第一崩点通常是显存：长 CoT 的 KV 随步数膨胀，叠加 scale 元数据与 BF16 补偿副本，并发上限先被容量卡住，而不是被算力卡住。第二崩点是 MoE 路由翻转引发的通信热点与分布偏差，它同时打击尾延迟与训练稳定性，且无法靠加卡缓解——加卡只扩大专家并行的 all-to-all 规模，热点更集中。第三崩点是误差估计回传通路的控制面拥塞，属于典型的“小流量、强同步”瓶颈。第四才是 MMA 算力本身，因为 NVFP4 已经把这块的余量做得很足。</p>\n<p>判据的用法是：在扩容前先测三个比值——KV 与权重的显存占比、路由翻转率随批大小的变化、误差回传的端到端时延占单步 decode 时延的比例。任一比值越过其主导区间，就说明下一个瓶颈已经迁移，继续按吞吐线性外推容量会失真。这也解释了为什么该算法的收益随模型规模与长 CoT 占比增大，而代价栏里同时写着补偿项抵消部分量化收益：规模越大，KV 与通信的 1/4 收益越显著，但补偿路径与路由对齐的固定开销也越难被摊薄。</p>\n<table class=\"mini\"><thead><tr><th>规模阶段</th><th>主导瓶颈</th><th>观测信号</th><th>应对方向</th></tr></thead><tbody><tr><td>小批、短序列</td><td>权重搬运</td><td>decode 吞吐随批线性上升</td><td>直接吃 NVFP4 带宽收益</td></tr><tr><td>长 CoT、中等并发</td><td>KV 显存与 scale 元数据</td><td>并发上限先于算力饱和</td><td>KV 分页与 block 粒度调优</td></tr><tr><td>大规模 MoE</td><td>路由翻转与 all-to-all 热点</td><td>P99 偏离均值、翻转率上升</td><td>路由对齐、精度降级策略</td></tr><tr><td>多节点分离部署</td><td>误差回传控制面</td><td>回传时延占比抬升</td><td>背驮回传、与权重同步解耦</td></tr></tbody></table>\n<p>最后落在具体机制上：扩容决策应绑定在误差估计的回传粒度上，而不是绑定在卡数上。回传粒度决定训练侧修正 $\\rho_t$ 的时效，也决定补偿项校准能否跟上批次切换；把粒度做粗可以省通信，但会让 KL 估计偏差在批次间累积，把粒度做细则控制面先崩。这个粒度与 KV block 大小、路由对齐的检查周期共同构成 NVFP4 rollout 在规模上的可调旋钮，调它们比调批大小更接近真实瓶颈。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-39\">三十九 · 量化收益在哪个环节被吃掉：带宽账、尾延迟与规模失效点</h3>\n<p>先把收益拆成可核算的两笔账。权重与KV压到NVFP4后，rollout引擎的显存占用与读取带宽需求降到BF16的1/4，这是纯收益；但logprob关键路径（最终lm_head与softmax）要BF16重算或叠加补偿项δ<sub>t</sub>，这部分算力不随量化缩小，反而在decode阶段被放大——因为它是每token必走的串行尾段，无法像GEMM那样靠批维度摊薄。设单token的GEMM时间为T<sub>q</sub>（NVFP4，随批增大近似线性摊薄），补偿路径时间为T<sub>c</sub>（BF16，近似常数），则单token有效时延为T<sub>q</sub>/B+T<sub>c</sub>，吞吐上限被T<sub>c</sub>钉死：批再大，也只能逼近1/T<sub>c</sub>。这就是规模上去后第一个崩的地方——不是显存，而是这条不摊薄的BF16尾段。长CoT批量生成时，样本长度越长，T<sub>c</sub>的累计占比越高，量化带来的decode吞吐提升被逐步稀释。</p>\n<p>第二处崩点在通信与同步。每轮rollout结束要把token、logprob与量化误差估计ε<sub>quant</sub>一并回传训练侧，误差估计是逐token的额外张量，回传量与序列长度成正比；在分离式预填/解码或跨节点rollout的拓扑下，这条回传链路与权重重新量化后同步到rollout引擎的链路形成一对反向流量，规模越大越容易在NCCL/NIXL通道上与KV传输争带宽。更隐蔽的是MoE：NVFP4下路由易翻转专家选择，若缺少路由对齐逻辑，同一token在不同量化批次走不同专家，此时误差补偿项δ<sub>t</sub>只覆盖了数值误差，覆盖不了“换了专家”这一结构性偏移，采样分布偏差直接越过ε<sub>align</sub>的界。规模越大、专家越多，翻转概率越高，这是比logprob精度更难补的失效条件。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的资源</th><th>表现</th></tr></thead><tbody><tr><td>批大小↑</td><td>BF16补偿路径算力</td><td>吞吐饱和于1/T<sub>c</sub>，尾延迟不降</td></tr><tr><td>序列长度↑</td><td>误差估计回传带宽</td><td>与权重同步争通道，rollout等待变长</td></tr><tr><td>专家数↑</td><td>路由一致性</td><td>专家翻转，δ<sub>t</sub>无法覆盖分布偏移</td></tr></tbody></table>\n<p>工程判断落在补偿项的完整性与回传契约上：ε<sub>quant</sub>必须与token、logprob同批回传，训练侧才能用ρ<sub>t</sub>=π<sub>θ</sub>(a<sub>t</sub>|s<sub>t</sub>)/π<sub>rollout</sub>(a<sub>t</sub>|s<sub>t</sub>)修正比率；一旦回传缺失或补偿项实现不完整，量化收益被抵消而比率仍失真，KL偏差累积后触发reward hacking。因此容量规划应按T<sub>c</sub>而非显存定SLO，并把路由对齐逻辑计入MoE的必选开销，而非可选优化。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-40\">四十 · 精度失败的三种指纹：分布偏移、比率失真、KL 漂移</h3>\n<p>NVFP4 rollout 的精度问题不会以单一报错的形式出现，而是沿着采样链路逐级放大，形成三类可区分的指纹。第一类是分布偏移：量化误差让 <span>softmax</span> 的尾部概率被截断或放大，采样分布与 BF16 参考的 TV 距离越过 <span>ε_align</span> 阈值。第二类是比率失真：训练侧用回传的 logprob 构造重要性采样比率 <span>ρ_t</span>，若 rollout logprob 系统性偏低或偏高，比率分布的方差被拉宽，梯度估计的噪声盖过信号。第三类是 KL 漂移：单步偏差在长 CoT 上累积，KL 估计单调偏离，最终表现为 reward hacking——策略学会利用量化误差而非真实奖励。</p>\n<p>诊断的关键是把这三类指纹映射到可观测的量上。工程上应在 rollout 引擎侧按 token 记录三个量：补偿后的 logprob、量化误差估计 <span>δ_t</span>、以及该 token 所属专家的路由 ID。训练侧则记录比率 <span>ρ_t</span> 的分位数（P50/P99）与 KL 的滑动均值。当 P99 比率在若干 rollout 步内持续抬升而 P50 稳定，说明尾部 token 的 logprob 补偿失效；当 KL 均值单向漂移且 <span>δ_t</span> 的绝对值同步增大，说明补偿项本身在累积误差。这两种模式对应不同的回滚动作，不能混为一谈。</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>代价在于监控本身：逐 token 记录 <span>δ_t</span> 与路由 ID 会增加回传带宽，在长 CoT 批量生成下这部分元数据量与 KV 带宽同阶。可行的折中是只对采样到的 token 记录完整误差估计，对被截断的候选只记录块级统计量，把回传开销压到与 logprob 同量级。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-41\">四十一 · MoE 路由翻转：补偿项覆盖不到的盲区</h3>\n<p>最隐蔽的失败模式是 MoE 路由翻转。NVFP4 量化后的门控权重在临界 token 上会改变 argmax 结果，同一 token 在不同量化批次下走不同专家。此时 logprob 补偿项 <span>δ_t</span> 只修正了被选中专家路径上的数值误差，却无法修正“选错专家”这一结构性偏差——两条专家路径的输出差异远超量化误差量级，TV 距离直接越界。表现是：整体 KL 尚可，但特定 token 子集（通常是门控分数接近并列的 token）的比率 <span>ρ_t</span> 出现离群尖刺。</p>\n<p>诊断手段是对路由做对齐审计：在 rollout 引擎与 BF16 参考引擎上并行跑同一批 token，比较专家选择的命中率，并按门控分数的边际（top-1 与 top-2 之差）分桶。边际小的桶命中率下降最明显，这个桶的大小直接决定路由对齐逻辑的必要性。工程判断是：若该桶占比不可忽略，就必须在门控计算路径保留 BF16 或加路由补偿，而不能只依赖 logprob 补偿。</p>\n<p>系统代价体现在算力上：门控路径的 BF16 重算只涉及一个小矩阵乘，相对整个前向可忽略，但它破坏了“全 NVFP4 前向”的流水线纯度，需要单独的 kernel 或融合分支，增加实现复杂度。若不这么做，代价转移到训练侧——路由翻转导致的分布偏差无法被比率修正覆盖，训练会在若干步后出现奖励与 KL 的背离。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-42\">四十二 · OOM 与批抖动：显存账本的两个漏口</h3>\n<p>NVFP4 把权重与 KV 压到 BF16 的 1/4，显存看似宽裕，但 OOM 仍会发生，漏口有两个。其一是补偿路径的临时缓冲：logprob 关键路径用 BF16 重算时，lm_head 的激活与 softmax 中间结果按 BF16 分配，在长 CoT 的最后一个 token 上这部分缓冲与 KV 峰值叠加。其二是批抖动：rollout 引擎按调度动态变化批大小，连续批处理在序列完成与新生请求插入时产生显存碎片，NVFP4 的 per-block scale 让每个块的分配粒度更细，碎片率上升。</p>\n<p>诊断应盯住两个指标：峰值显存与批大小的相关系数，以及碎片率（已分配但未使用的块占比）。若峰值显存随批大小线性上升而无平台，说明补偿缓冲未被复用；若碎片率随请求完成率波动，说明块分配器需要按 NVFP4 的块粒度重新调参。工程动作是把补偿缓冲做成按 SM 复用的常驻 scratch，并把 KV 块大小对齐到 per-block scale 的粒度，避免跨块边界的部分分配。</p>\n<p>批抖动的另一面是吞吐抖动：批大小频繁跳变会让张量核心的利用率在 MMA 形状切换时掉档。监控应记录每轮 decode 的批大小分布与对应吞吐，若吞吐随批大小的方差过大，说明调度器的批组装策略与 NVFP4 kernel 的偏好形状不匹配，需要约束批大小的取值集合而非放任动态变化。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-43\">四十三 · 尾延迟尖刺：从 P99 到单 token 归因</h3>\n<p>尾延迟尖刺在 NVFP4 rollout 上有独特成因：量化误差补偿项的计算是条件触发的（仅对 logprob 关键路径），当一批请求中恰好有多个长 CoT 同时到达采样阶段，补偿路径的算力需求瞬时叠加，形成尖刺。另一成因是 MoE 路由对齐逻辑的分支：命中临界桶的 token 走 BF16 门控，这条分支的延迟高于主路径，若临界 token 在时间上聚集，P99 被拉高。</p>\n<p>诊断要把 P99 拆到单 token 归因：记录每个 token 是否走了补偿路径、是否触发路由对齐分支、以及该 token 的 decode 耗时。若 P99 尖刺与补偿路径的并发数高度相关，解法是给补偿路径预留固定的算力配额而非按需抢占；若与路由对齐分支相关，解法是把门控重算提前到预填阶段批量处理，避免在 decode 的关键路径上分支。</p>\n<p>系统代价是预留配额会降低平均吞吐：固定配额意味着在无尖刺时这部分算力闲置。工程判断取决于 SLO 形态——若 SLO 以 P99 为主，预留是值得的；若以平均吞吐为主，则应改为对补偿路径做批处理合并，把多个请求的 logprob 重算拼成一次 MMA，用批的规模摊薄分支开销。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-44\">四十四 · 监控埋点与回滚分级</h3>\n<p>监控体系应围绕三个层次埋点。引擎层记录每轮 decode 的批大小、峰值显存、碎片率、补偿路径并发数、路由对齐分支命中率；token 层记录 logprob、<span>δ_t</span>、路由 ID、是否走补偿路径；训练层记录 <span>ρ_t</span> 的分位数、KL 滑动均值、奖励与 KL 的背离度。三层通过请求 ID 关联，使得任何一次尾延迟尖刺或比率离群都能回溯到具体的 token 与分支。</p>\n<p>回滚必须分级，因为不同失败模式的修复代价差异巨大。一级回滚是关闭路由对齐分支之外的补偿优化（如批处理合并），恢复到保守的逐请求补偿，代价是吞吐下降但精度不变。二级回滚是把 logprob 路径整体切回 BF16 重算，放弃该路径的量化收益，权重与 KV 仍保持 NVFP4，代价是 decode 吞吐的部分回退。三级回滚是 rollout 引擎整体退回 BF16 权重，仅在精度告警持续且二级回滚无效时触发。分级的意义在于：多数精度问题源于补偿项实现不完整或误差估计未回传，一级回滚即可止血，不必牺牲全部量化收益。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主监控量</th><th>首选回滚</th><th>代价</th></tr></thead><tbody><tr><td>分布偏移越界</td><td>TV 距离、δ_t 绝对值</td><td>二级：logprob 路径 BF16</td><td>decode 吞吐部分回退</td></tr><tr><td>比率失真</td><td>ρ_t 的 P99/P50</td><td>一级：恢复逐请求补偿</td><td>吞吐下降，精度不变</td></tr><tr><td>路由翻转</td><td>专家命中率、边际分桶</td><td>门控路径 BF16</td><td>流水线纯度受损</td></tr><tr><td>OOM / 批抖动</td><td>峰值显存、碎片率</td><td>约束批大小取值集合</td><td>调度灵活性下降</td></tr><tr><td>尾延迟尖刺</td><td>补偿路径并发数</td><td>预留算力配额</td><td>平均吞吐下降</td></tr></tbody></table>\n<p>回滚的触发条件必须是确定性的阈值而非趋势判断：TV 距离连续若干步越过 <span>ε_align</span>、<span>ρ_t</span> 的 P99 超过 P50 的固定倍数、KL 滑动均值单向漂移超过设定带宽。这些阈值应在部署配方阶段就与 SLO 一起标定，避免在训练崩溃后才被动调整。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-45\">四十五 · 误差估计回传：把诊断变成修正</h3>\n<p>诊断的终点不是告警，而是让训练侧能修正。核心机制是把 <span>δ_t</span> 与 logprob 一同回传，训练侧在构造比率时用误差估计做一阶修正：<span>ρ_t</span> 的分母不再是原始 rollout logprob，而是加上 <span>δ_t</span> 后的补偿值。这样量化误差在比率层面被部分抵消，而不是留给 KL 估计去累积。若误差估计未回传，训练侧只能看到失真的 logprob，任何监控都只能事后发现崩溃，无法事前修正。</p>\n<div class=\"formula\">$$\\tilde{p}_t=\\mathrm{softmax}_{\\mathrm{BF16}}(W_{\\mathrm{deq}}h_t+\\delta_t),\\quad \\delta_t\\approx \\epsilon_{\\mathrm{quant}}(W,h_t),\\quad \\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)}$$</div>\n<p>代价是回传链路与训练侧计算的增量：<span>δ_t</span> 的序列化与传输占用带宽，训练侧的修正计算增加少量算力。工程判断是这笔开销必须付——它把“量化误差导致比率失真”从不可观测的漂移变成可修正的已知项，是 NVFP4 rollout 稳定化闭环的最后一环。若带宽紧张，可只回传采样 token 的 <span>δ_t</span> 并对被截断候选做块级聚合，修正精度略降但闭环仍然成立。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-46\">四十六 · 量化误差对齐的失效边界与回滚判据</h3>\n<p>误差对齐把采样分布与 BF16 参考的 TV 距离压到 $\\epsilon_{\\text{align}}$ 以内，但这条界只在补偿链路完整时成立。失效的第一类条件是补偿项覆盖不全：若 lm_head 与 softmax 走了 BF16 重算，而 MoE 路由仍由 NVFP4 激活直接打分，则同一 token 在不同量化批次下可能翻转专家选择，采样分布偏差落在 logprob 补偿项的作用域之外，此时 $\\delta_t$ 只能修正数值误差，无法修正“走了另一个专家”这一结构性偏移。第二类条件是误差估计断链：$\\epsilon_{\\text{quant}}$ 未随 token 与 logprob 一同回传，训练侧拿不到修正量，重要性比率 $\\rho_t$ 按失真的 logprob 计算，KL 估计偏差随步数累积，最终表现为 reward hacking 或 loss 尖刺而非显式的数值异常。</p>\n<p>诊断上应把监控拆成三层，分别对应三种可观测信号。分布层：以固定 prompt 集周期性跑 BF16 参考前向，计算 $D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}})$ 与 $\\rho_t$ 的分位数，TV 距离越界或 $\\rho_t$ 方差抬升即为对齐失效的直接证据。路由层：统计同一 token 在 NVFP4 与 BF16 下专家选择的翻转率，翻转率非零且集中于少数层时，说明该层路由打分对量化过于敏感，需对该层路由单独保留高精度打分。系统层：decode 吞吐、单样本生成时延、KV 带宽占用与显存水位，用于区分“精度问题”与“容量问题”——前者表现为分布指标漂移而吞吐正常，后者表现为批抖动与尾延迟尖刺。</p>\n<p>回滚不应是全局开关，而应按粒度分级。最小粒度是单层回滚：把翻转率超阈的 MoE 路由层或 softmax 路径切回 BF16 重算，代价是该层算力回到 BF16 水平，抵消的只是这部分量化收益。中粒度是 logprob 路径整体回滚，保留 NVFP4 权重与 KV 存储以维持 1/4 带宽收益，仅最终 lm_head 与 softmax 走 BF16，这是精度与吞吐的折中点。最大粒度是整轮 rollout 回滚到 BF16 引擎，代价是 decode 吞吐回落、长 CoT 样本生成时间回升，仅在 $\\rho_t$ 发散且训练侧已出现崩溃征兆时启用。判据应写成可执行的阈值组合：TV 距离越界且路由翻转率非零，触发单层回滚；$\\rho_t$ 分位数越界但翻转率为零，触发 logprob 路径回滚；两者同时越界并伴随 loss 尖刺，直接整轮回滚并冻结该轮样本。</p>\n<p>系统代价必须计入容量规划：BF16 重算路径使 logprob 段的算力密度上升，在长 CoT 批量生成下这部分算力与 NVFP4 张量核心的吞吐收益形成对冲，实际端到端收益取决于 logprob 段占总前向的比例；MoE 路由对齐逻辑增加每 token 的额外比较与分支，抬高了调度器的批内方差，进而放大批抖动。工程判断是：把 $\\epsilon_{\\text{quant}}$ 的回传当作硬约束而非可选优化，一旦断链，任何分布层监控都失去修正依据，回滚只能靠事后指标被动触发。</p>\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-47\">四十七 · 对照维度：先分清\"哪个误差在动\"</h3>\n<p>同族算法在工程上最容易混为一谈，因为它们都表现为\"rollout 的 logprob 与训练侧不一致\"。但把误差源拆开，选型立刻清晰。批不变内核处理的是<b>批组成变化</b>导致的归约顺序差异——同一 token 在不同 batch 里得到不同 logprob，误差来自浮点求和顺序而非数值精度；异步权重同步处理的是<b>时间错位</b>——rollout 用的策略版本落后于训练侧，误差来自策略漂移；本算法处理的是<b>量化误差</b>——权重与激活压到 NVFP4 后，采样分布本身发生偏移，误差来自 4bit 表示能力。三者可以叠加发生，但修复手段互不替代：批不变内核不会让 NVFP4 的分布偏移收敛，误差补偿项也不会消除 batch 归约顺序带来的抖动。</p>\n<p>判断方法很直接：把同一 batch 的组成固定、把权重版本冻结，只切换精度路径（BF16 与 NVFP4 各跑一遍），若 logprob 差异仍然存在且随 token 位置累积，就是量化误差在起作用；若固定精度后差异随 batch 大小变化，则是批不变性问题。这个对照实验的代价是一次双路径前向，显存上需要同时驻留 BF16 参考权重与 NVFP4 权重，对长 CoT 批量生成而言是短时开销，但能避免把补偿项写到错误的层上。</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>这条不等式是选型的量化判据：只有当补偿项 δ 把 TV 距离压到 ε_align 以内，重要性采样比率 ρ_t 才不会发散。若实测 TV 距离随生成长度单调上升，说明补偿项只覆盖了单步误差而未覆盖累积误差，此时应退回 BF16 logprob 路径而不是继续加大量化档位。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-48\">四十八 · 决策表：四条稳定化路径的适用条件</h3>\n<p>下表把同族四条路径按\"误差源—修复位置—代价形态—何时不该用\"排列。表中不写具体卡数与阈值，因为材料未给出，工程上应按实测 TV 距离与 ρ_t 方差自行标定。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>误差源</th><th>修复位置</th><th>主要代价</th><th>不适用条件</th></tr></thead><tbody>\n<tr><td>批不变内核</td><td>batch 组成导致的归约顺序差异</td><td>attention/softmax 归约内核</td><td>内核实现复杂度，长序列下归约开销上升</td><td>单请求串行生成、批大小恒定的场景收益趋零</td></tr>\n<tr><td>异步权重同步</td><td>rollout 与训练的策略版本错位</td><td>权重分发与版本标记</td><td>显存双份权重驻留、版本一致性校验</td><td>策略更新极频繁、无法容忍任何陈旧 logprob 的场景</td></tr>\n<tr><td>NVFP4 量化稳定化（本算法）</td><td>4bit 量化引入的采样分布偏移</td><td>lm_head/softmax 的 BF16 重算与 δ 补偿</td><td>logprob 路径额外算力，MoE 路由对齐逻辑</td><td>模型规模小、长 CoT 占比低，量化收益不足以覆盖补偿开销</td></tr>\n<tr><td>前缀 KV 共享</td><td>重复前缀的重复计算</td><td>KV 缓存复用层</td><td>缓存命中率低时显存浪费</td><td>请求前缀高度分散、共享率低的负载</td></tr>\n</tbody></table>\n<p>选型顺序建议按误差贡献排序：先用对照实验测出三条误差源各自对 ρ_t 方差的贡献，再决定投入。若量化误差贡献最大，本算法优先；若版本错位贡献最大，异步同步优先，此时即便量化误差存在，也可先用 BF16 logprob 路径兜住，把量化收益让给 KV 带宽而非 logprob 精度。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-49\">四十九 · 与批不变内核的交叉：补偿项不能替代归约确定性</h3>\n<p>一个常见误判是认为\"既然 logprob 已经用 BF16 重算并加了 δ 补偿，batch 归约顺序的差异就被吸收了\"。这在数值上不成立：批不变性差异来自不同 batch 下 softmax 分母的求和顺序，量级随序列长度与 batch 组成漂移，而 δ 是针对量化误差标定的固定补偿，二者不是同一量纲。工程上必须两条都做，但可以分工——把 lm_head 与 softmax 的 BF16 重算作为共享路径，批不变内核只保证这条路径内部的归约顺序确定，从而让 δ 的标定在固定归约顺序下可复现。</p>\n<p>伪代码层面的分工如下：</p>\n<ul>\n<li>前向主体：NVFP4 权重 × NVFP4 激活做 MMA，累加器 FP32，反量化回 BF16；</li>\n<li>logprob 路径：固定归约顺序的 BF16 softmax，叠加 δ_t；</li>\n<li>回传：token、logprob、δ_t 与量化误差估计 ε_quant 一并写入样本记录；</li>\n<li>训练侧：用 ε_quant 修正 ρ_t，用固定归约顺序保证同一 token 的 logprob 可复现。</li>\n</ul>\n<p>代价在于这条共享路径把两套机制的实现耦合在一个内核里，调试时无法单独关闭其一；收益是避免了\"补偿项掩盖归约抖动\"的假稳定——那种情况下训练看似不崩，但 KL 估计的方差被系统性低估，容量规划会按错误的 SLO 排布。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-50\">五十 · 与异步权重同步的交叉：陈旧策略下的量化误差会被放大</h3>\n<p>异步同步让 rollout 用落后若干步的策略权重生成，此时 ρ_t 本身已经偏离 1；若再叠加 NVFP4 的分布偏移，两个偏差相乘而非相加。设 rollout 策略为 π_rollout、训练侧目标为 π_θ，则</p>\n<div class=\"formula\">$$\\rho_t = \\frac{\\pi_{\\theta}(a_t|s_t)}{\\pi_{\\text{rollout}}(a_t|s_t)}$$</div>\n<p>分母中的 π_rollout 是 NVFP4 采样分布，分子是训练侧 BF16/FP8 更新后的分布。若 δ 补偿不完整，分母被系统性压偏，ρ_t 的方差在长 CoT 上随 token 数累积放大，训练侧看到的梯度会被少数高比率 token 主导。工程判断是：异步同步的版本落后步数越多，对 δ 的精度要求越高；当落后步数超过一个阈值（由实测 ρ_t 方差决定），应把 logprob 路径整体退回 BF16，而不是在 NVFP4 上继续加补偿项。</p>\n<p>具体例子：MoE 模型在 NVFP4 下路由易翻转专家选择，同一 token 在不同量化批次走不同专家。异步同步又让不同批次的权重版本不同，两因素叠加使同一 token 的 logprob 在两次 rollout 间出现无法用 δ 解释的差异。此时正确做法是给路由加对齐逻辑（固定路由判决的数值路径），并把版本标记写入样本记录，让训练侧能按版本分组修正 ρ_t，而不是笼统地乘一个全局补偿系数。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-51\">五十一 · 与分页 KV、前缀共享的交叉：省带宽的收益要不要让给 logprob</h3>\n<p>NVFP4 存储 KV 把带宽需求降到 BF16 的 1/4，这是本算法吞吐收益的主要来源之一。但 KV 量化与 logprob 补偿是两条独立的误差链：KV 量化影响 attention 输出的精度，进而影响隐状态 h_t，最终反映在 logprob 上；而 δ 补偿通常只标定在 lm_head 与 softmax 段。若 KV 也用 NVFP4，δ 的标定必须覆盖 attention 段的误差传播，否则 TV 距离的上界 ε_align 无法保证。</p>\n<p>与分页 KV 批量 Rollout 交叉时，分页带来的块边界会改变 attention 的归约分段，使 KV 量化误差的分布随块大小变化；与前缀 KV 共享交叉时，共享前缀的 KV 若以 NVFP4 缓存，被多个请求复用时误差被重复计入不同样本的 logprob。工程取舍是：把 KV 的 NVFP4 存储与 logprob 路径的 BF16 重算解耦——KV 保持 NVFP4 省带宽，attention 输出在进入 logprob 关键路径前用 BF16 残差校正一次，代价是每层一次额外的反量化与校正算力，收益是 δ 的标定可以只针对 lm_head 段，降低实现复杂度。</p>\n<p>容量规划上要计入这笔账：KV 压到 1/4 释放的显存可以换更大的批或更长的上下文，但 logprob 路径的 BF16 校正会占用一部分算力预算，二者在 SLO 上不是免费互换。若负载以短样本为主，KV 量化收益有限而校正开销固定，此时应优先保证 logprob 精度而非追求 KV 压缩率。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-52\">五十二 · 选型判据落在 ρ_t 方差与 TV 距离的实测上</h3>\n<p>四条路径的最终判据不是架构参数，而是两个可观测量：采样分布与 BF16 参考的 TV 距离是否稳定在 ε_align 以内，以及 ρ_t 的方差是否随生成长度收敛。工程上应把这两个量作为 rollout 引擎的常驻监控项，按模型、按负载形态分别标定，而不是全局套用一个补偿系数。当 TV 距离随长度上升而 ρ_t 方差同步放大，说明误差在累积而非单步，此时任何单点补偿都不够，应退回 BF16 logprob 路径并把量化收益限制在 KV 与权重带宽上；当 TV 距离受控但 ρ_t 方差仍大，问题在版本错位或批组成，应转向异步同步与批不变内核，而非继续调 δ。</p>\n<p>最后一个工程判断：MoE 模型的路由对齐逻辑必须与 δ 补偿同批上线，因为路由翻转造成的分布偏差无法被 lm_head 段的补偿项覆盖——补偿项作用在已选专家的输出上，而路由翻转改变的是专家选择本身。缺少路由对齐时，即便 TV 距离在单层看似受控，端到端的采样分布仍会偏移，且这种偏移不随 δ 增大而收敛。</p>\n\n<h3 id=\"alg-nvfp4-rollout-quant-stable-sec-53\">五十三 · 量化误差对齐的适用边界与同族算法选型</h3>\n<p>本算法在算法谱系中的定位必须精确：批不变内核处理的是 batch 组成变化导致的 logprob 不可复现，异步权重同步处理的是 rollout 与训练的串行等待，而 NVFP4 rollout 量化稳定处理的是 4bit 量化本身引入的采样分布偏移。三者正交，可以叠加，但代价结构完全不同。前两者的开销主要落在调度与通信层，本算法的开销直接落在前向计算路径上——logprob 关键路径的 BF16 重算或补偿项是实打实的额外算力，会抵消一部分量化收益。因此选型的第一判据不是“要不要稳”，而是“量化收益是否大于补偿成本”。当模型以 decode 为主、长 CoT 占比高、KV 带宽是瓶颈时，权重与 KV 降至 BF16 的 1/4 带来的吞吐增益足以覆盖补偿开销；反之，若序列短、批内 token 数少、算力而非带宽受限，BF16 重算 lm_head 与 softmax 的相对占比上升，量化收益被吃掉，此时应退回 BF16 rollout 或仅对权重做 NVFP4 而激活保留 BF16。</p>\n<p>第二个判据是模型结构是否含 MoE。MoE 路由在 NVFP4 下易翻转专家选择，若缺少路由对齐逻辑，同一 token 在不同量化批次下走不同专家，采样分布偏差无法被 logprob 补偿项覆盖——补偿项只作用于最终 lm_head 与 softmax，管不到中间层的离散路由决策。这类偏差在 TV 距离上表现为不可约的偏移：</p>\n<div class=\"formula\">$$D_{\\text{TV}}(p_{\\text{BF16}}, p_{\\text{NVFP4}}) \\le \\tfrac{1}{2}\\sum_i \\left|\\text{softmax}(z_i^{\\text{BF16}}) - \\text{softmax}(\\tilde z_i^{\\text{NVFP4}} + \\delta_i)\\right| \\le \\epsilon_{\\text{align}}$$</div>\n<p>其中 $\\delta_i$ 只对连续路径有效，路由翻转引入的是离散跳变，必须靠额外的路由对齐逻辑（如路由 logits 的 BF16 重算或 top-k 边界保护）单独压制。稠密模型没有这一项，选型时可以只评估补偿成本；MoE 模型则必须把路由对齐的实现复杂度计入决策。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选 NVFP4 + 误差对齐</th><th>选 BF16 rollout</th></tr></thead><tbody><tr><td>长 CoT 占比高、KV 带宽受限</td><td>是，1/4 带宽收益主导</td><td>否</td></tr><tr><td>序列短、算力受限</td><td>否，补偿开销占比过高</td><td>是</td></tr><tr><td>稠密模型</td><td>是，补偿项可覆盖偏差</td><td>备选</td></tr><tr><td>MoE 且无路由对齐</td><td>否，偏差不可约</td><td>是</td></tr><tr><td>误差估计无法回传训练侧</td><td>否，比率仍失真</td><td>是</td></tr></tbody></table>\n<p>第三个判据是闭环完整性。量化误差估计必须随 token 与 logprob 一同回传训练侧，训练侧才能用 $\\rho_t = \\pi_{\\theta}(a_t|s_t)/\\pi_{\\text{rollout}}(a_t|s_t)$ 修正重要性比率；若回传链路缺失或补偿项实现不完整，量化收益被抵消且比率仍会失真，KL 估计偏差累积后触发 reward hacking 或训练崩溃。工程判断应落在这一点上：把误差估计当作与 logprob 同级的一等输出字段，在 rollout 引擎的返回结构中固定下来，而不是作为可选调试信息。只有当“NVFP4 前向 + BF16 关键路径补偿 + 误差估计回传”三者同时成立，本算法才进入可用区间；缺任一环，应降级到 BF16 rollout 或仅权重 4bit 的保守配置。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 奖励模型与验证器推理</td></tr><tr><td>解决什么</td><td>Blackwell的NVFP4张量核心可将rollout权重与激活压到4bit，吞吐翻倍，但RL rollout的采样…</td></tr><tr><td>一句话机制</td><td>rollout用NVFP4做权重与KV存储以省带宽，但对logprob计算路径保留BF16残差校正（量化误差对齐），并…</td></tr><tr><td>代价与失效</td><td>logprob路径的BF16重算或补偿项增加额外算力与实现复杂度，抵消部分量化收益；MoE模型的路由在NVFP4下易翻转专家选择，需额外路…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-rollout-quant-stable · 共 8 个片段</p>\n";break;}}})();
